-- Schema-only baseline audited from production on 2026-09-10. No customer data.
-- The repository's early migrations are history placeholders, not a bootstrap.
-- Auth shims below are local test infrastructure only.
create schema if not exists private;
create schema if not exists auth;
create role anon; create role authenticated; create role service_role bypassrls;
create table auth.users(id uuid primary key);
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create function auth.jwt() returns jsonb language sql stable as $$select coalesce(nullif(current_setting('request.jwt.claims',true),'')::jsonb,'{}'::jsonb)$$;
create function auth.role() returns text language sql stable as $$select auth.jwt()->>'role'$$;
set check_function_bodies=off;
create table private.public_renewal_authorizations (
  "nonce_hash" text not null,
  "kiosk_id" bigint not null,
  "expires_at" timestamp with time zone not null,
  "consumed_at" timestamp with time zone
);
create table public.app_permissions (
  "permission" text not null,
  "display_name" text not null,
  "sort_order" integer default 0 not null,
