alter table public.app_permissions add constraint app_permissions_key_check CHECK (((permission = lower(btrim(permission))) AND (permission ~ '^[a-z0-9][a-z0-9-]*$'::text)));
alter table public.app_permissions add constraint app_permissions_pkey PRIMARY KEY (permission);
alter table public.audit_logs add constraint audit_logs_actor_type_check CHECK (((actor_type IS NULL) OR (actor_type = ANY (ARRAY['staff'::text, 'public'::text, 'system'::text, 'database_trigger'::text]))));
alter table public.audit_logs add constraint audit_logs_legacy_log_id_key UNIQUE (legacy_log_id);
alter table public.audit_logs add constraint audit_logs_pkey PRIMARY KEY (id);
alter table public.business_types add constraint business_types_pkey PRIMARY KEY (id);
alter table public.business_types add constraint business_types_price_per_month_check CHECK ((price_per_month >= (0)::numeric));
alter table public.business_types add constraint uq_business_type UNIQUE (category_id, name);
alter table public.categories add constraint categories_name_key UNIQUE (name);
alter table public.categories add constraint categories_pkey PRIMARY KEY (id);
alter table public.customer_user_links add constraint customer_user_links_pkey PRIMARY KEY (id);
alter table public.customer_user_links add constraint customer_user_links_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'revoked'::text])));
alter table public.customer_user_links add constraint customer_user_links_type_check CHECK ((link_type = ANY (ARRAY['owner'::text, 'manager'::text, 'billing_contact'::text, 'ttc_actor'::text])));
alter table public.customers add constraint customers_facebook_id_key UNIQUE (facebook_id);
alter table public.customers add constraint customers_phone_key UNIQUE (phone);
alter table public.customers add constraint customers_pkey PRIMARY KEY (id);
alter table public.customers add constraint customers_status_check CHECK (((status)::text = ANY ((ARRAY['active'::character varying, 'pending'::character varying, 'inactive'::character varying, 'potential'::character varying, 'suspended'::character varying, 'expired'::character varying])::text[])));
alter table public.customers add constraint customers_total_kiosks_check CHECK ((total_kiosks >= 0));
alter table public.customers add constraint customers_total_paid_check CHECK ((total_paid >= (0)::numeric));
alter table public.kiosks add constraint kiosks_pkey PRIMARY KEY (id);
alter table public.kiosks add constraint kiosks_status_check CHECK (((status)::text = ANY ((ARRAY['active'::character varying, 'inactive'::character varying, 'expired'::character varying, 'warning'::character varying, 'pending'::character varying, 'suspended'::character varying])::text[])));
