CREATE OR REPLACE FUNCTION public.admin_cancel_awaiting_registration(request_id_input bigint, reason_input text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  request_record public.registration_requests%rowtype;
  batch_record public.registration_batches%rowtype;
  payment_record public.payments%rowtype;
  cancelled_at timestamptz := pg_catalog.now();
  affected_requests bigint[];
begin
  if auth.uid() is null or not exists (
    select 1 from public.user_roles ur
    where ur.user_id = auth.uid()
      and pg_catalog.lower(ur.role) = 'admin'
      and ur.is_active
  ) then
    raise exception 'Bạn không có quyền hủy hồ sơ chờ thanh toán.' using errcode = '42501';
  end if;
  if nullif(pg_catalog.btrim(reason_input), '') is null then
    raise exception 'Cần nhập lý do hủy.' using errcode = '22023';
  end if;

  select * into request_record
  from public.registration_requests
  where id = request_id_input
  for update;
  if not found then
    raise exception 'Không tìm thấy hồ sơ đăng ký.' using errcode = 'P0002';
  end if;
  if request_record.status = 'cancelled' then
    return pg_catalog.jsonb_build_object('already_cancelled', true, 'request_id', request_record.id);
  end if;
  if request_record.status <> 'awaiting_payment' then
    raise exception 'Chỉ hồ sơ chờ thanh toán mới có thể hủy.' using errcode = '22023';
  end if;

  if request_record.registration_batch_id is not null then
    select * into batch_record
    from public.registration_batches
    where id = request_record.registration_batch_id
    for update;
    select * into payment_record
    from public.payments
    where id = batch_record.payment_id
    for update;

    if payment_record.payment_status = 'completed'
      or exists (
        select 1 from public.payos_orders o
        where o.payment_id = payment_record.id and o.status = 'paid'
      )
      or exists (
        select 1
        from public.registration_batch_items i
        join public.kiosks k on k.id = i.kiosk_id
        where i.batch_id = batch_record.id and k.status = 'active'
      ) then
      raise exception 'Hồ sơ đã có thanh toán hoàn tất hoặc Kiosk hoạt động.' using errcode = '23505';
    end if;

    select pg_catalog.array_agg(i.registration_request_id order by i.registration_request_id)
    into affected_requests
    from public.registration_batch_items i
    where i.batch_id = batch_record.id;

    update public.payos_orders
    set status = 'cancelled', active_slot = false,
        processed_at = coalesce(processed_at, cancelled_at), updated_at = cancelled_at,
        provider_payload = coalesce(provider_payload, '{}'::jsonb)
          || pg_catalog.jsonb_build_object('admin_logical_cancel', true)
    where payment_id = payment_record.id and status = 'pending';

    if payment_record.payment_status = 'pending' then
      perform pg_catalog.set_config('app.payment_workflow_action', 'cancel', true);
      update public.payments
      set payment_status = 'cancelled',
          note = pg_catalog.concat_ws(E'\n', nullif(note, ''), 'Admin cancelled: ' || pg_catalog.btrim(reason_input))
      where id = payment_record.id;
    end if;
    update public.registration_batches
    set status = 'cancelled', updated_at = cancelled_at
    where id = batch_record.id;

    update public.kiosks k
    set status = 'inactive'
    where k.status = 'pending'
      and exists (
        select 1 from public.registration_batch_items i
        where i.batch_id = batch_record.id and i.kiosk_id = k.id
      )
      and not exists (
        select 1 from public.payments completed_payment
        where completed_payment.kiosk_id = k.id
          and completed_payment.payment_status = 'completed'
      );
  else
    affected_requests := array[request_record.id];
  end if;

  update public.registration_requests
  set status = 'cancelled',
      reviewed_at = cancelled_at,
      reviewed_by = auth.uid(),
      rejection_reason = pg_catalog.btrim(reason_input),
      metadata = coalesce(metadata, '{}'::jsonb) || pg_catalog.jsonb_build_object(
        'cancelled_source', 'admin', 'cancelled_at', cancelled_at
      )
  where id = any(affected_requests);

  perform private.write_ttc_audit(
    'Registration', 'admin_cancel', 'registration_requests', request_id_input::text,
    pg_catalog.to_jsonb(request_record),
    pg_catalog.jsonb_build_object(
      'status', 'cancelled',
      'batch_id', request_record.registration_batch_id,
      'affected_request_ids', affected_requests
    ),
    pg_catalog.btrim(reason_input)
  );

  return pg_catalog.jsonb_build_object(
    'already_cancelled', false,
    'request_id', request_id_input,
    'batch_id', request_record.registration_batch_id,
    'affected_request_ids', affected_requests
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_manual_renew_kiosk(kiosk_id_input bigint, months_input integer, start_date_input date, base_amount_input numeric, discount_input numeric DEFAULT 0, discount_reason_input text DEFAULT NULL::text, payment_method_input text DEFAULT NULL::text, note_input text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor public.user_roles%rowtype;
  kiosk_record public.kiosks%rowtype;
  customer_record public.customers%rowtype;
  payment_record public.payments%rowtype;
  confirmation_date date := (pg_catalog.now() at time zone 'Asia/Ho_Chi_Minh')::date;
  confirmation_timestamp timestamptz := pg_catalog.now();
  effective_start_date date;
  calculated_end_date date;
  normalized_discount numeric := coalesce(discount_input, 0);
  actual_amount numeric;
  normalized_method text := lower(trim(coalesce(payment_method_input, '')));
begin
  actor := private.assert_payment_permission();
  if lower(actor.role) <> 'admin' then
    raise exception 'Chỉ Admin được xác nhận gia hạn thủ công.' using errcode = '42501';
  end if;

  if months_input is null or months_input < 1 then
    raise exception 'Số tháng phải là số nguyên lớn hơn 0.' using errcode = '22023';
  end if;
  if base_amount_input is null or base_amount_input < 0 then
    raise exception 'Giá gốc không hợp lệ.' using errcode = '22023';
  end if;
  if normalized_discount < 0 or normalized_discount > base_amount_input then
    raise exception 'Giảm giá phải từ 0 đến giá gốc.' using errcode = '22023';
  end if;
  if normalized_discount > 0 and nullif(trim(discount_reason_input), '') is null then
    raise exception 'Lý do giảm giá là bắt buộc khi có giảm giá.' using errcode = '22023';
  end if;
  if normalized_method not in ('transfer', 'cash', 'other') then
    raise exception 'Phương thức thanh toán không hợp lệ.' using errcode = '22023';
  end if;

  select * into kiosk_record
  from public.kiosks
  where id = kiosk_id_input
  for update;
  if not found then
    raise exception 'Không tìm thấy Kiosk.' using errcode = 'P0002';
  end if;
  if kiosk_record.customer_id is null then
    raise exception 'Kiosk thiếu khách hàng.' using errcode = '22023';
  end if;

  select * into customer_record
  from public.customers
  where id = kiosk_record.customer_id
  for update;
  if not found then
    raise exception 'Khách hàng của Kiosk không tồn tại.' using errcode = 'P0002';
  end if;

  -- start_date_input remains in the public signature for client compatibility,
  -- but the locked Kiosk row and confirmation date are authoritative.
  effective_start_date := case
    when kiosk_record.end_date is not null and kiosk_record.end_date >= confirmation_date
      then kiosk_record.end_date + 1
    else confirmation_date
  end;
  calculated_end_date := (
    effective_start_date
    + pg_catalog.make_interval(months => months_input)
    - interval '1 day'
  )::date;

  actual_amount := base_amount_input - normalized_discount;
  insert into public.payments(
    customer_id, kiosk_id, start_date, end_date, months, price_per_month,
    discount, discount_reason, total_amount, payment_method, payment_status,
    confirmed_by, confirmed_at, note, transaction_type, service_month_delta
  ) values (
    customer_record.id, kiosk_record.id, effective_start_date, calculated_end_date,
    months_input, base_amount_input / months_input, normalized_discount,
    nullif(trim(discount_reason_input), ''), actual_amount, normalized_method, 'pending',
    null, null, nullif(trim(note_input), ''), 'standard', 0
  ) returning * into payment_record;

  perform pg_catalog.set_config('app.payment_workflow_action', 'confirm', true);
  update public.payments
  set payment_status = 'completed',
      confirmed_by = actor.user_id::text,
      confirmed_at = confirmation_timestamp
  where id = payment_record.id
  returning * into payment_record;

  update public.kiosks
  set status = 'active',
      end_date = calculated_end_date
  where id = kiosk_record.id;

  update public.customers
  set status = case when lower(coalesce(status, '')) = 'pending' then 'active' else status end,
      total_kiosks = (select count(*) from public.kiosks k where k.customer_id = customer_record.id)
  where id = customer_record.id;

  perform private.write_payment_audit(
    'admin_manual_renewal',
    jsonb_build_object('kiosk', to_jsonb(kiosk_record)),
    jsonb_build_object(
      'payment', to_jsonb(payment_record),
      'kiosk_id', kiosk_record.id,
      'original_activation_date', kiosk_record.start_date,
      'old_expiry_date', kiosk_record.end_date,
      'requested_start_date', start_date_input,
      'renewal_period_start', effective_start_date,
      'renewal_period_end', calculated_end_date,
      'months', months_input,
      'base_amount', base_amount_input,
      'discount', normalized_discount,
      'actual_amount', actual_amount,
      'payment_source', 'admin_manual'
    ),
    coalesce(nullif(trim(note_input), ''), 'Admin xác nhận đã thanh toán và gia hạn Kiosk'),
    actor
  );

  return jsonb_build_object(
    'payment', to_jsonb(payment_record),
    'kiosk', (select to_jsonb(k) from public.kiosks k where k.id = kiosk_record.id),
    'period', jsonb_build_object('start_date', effective_start_date, 'end_date', calculated_end_date),
    'payment_source', 'admin_manual'
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.cancel_payment(payment_id_input bigint, reason_input text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor public.user_roles%rowtype;
  payment_record public.payments%rowtype;
  before_record public.payments%rowtype;
begin
  actor := private.assert_payment_permission();

  if nullif(trim(reason_input), '') is null then
    raise exception 'Lý do hủy là bắt buộc.';
  end if;

  select * into payment_record
  from public.payments
  where id = payment_id_input
  for update;

  if not found or lower(payment_record.payment_status) <> 'pending' then
    raise exception 'Chỉ thanh toán Pending mới được hủy.';
  end if;

  before_record := payment_record;
  perform set_config('app.payment_workflow_action', 'cancel', true);

  update public.payments
  set payment_status = 'cancelled'
  where id = payment_record.id
  returning * into payment_record;

  perform private.write_payment_audit(
    'cancel',
    to_jsonb(before_record),
    to_jsonb(payment_record),
    reason_input,
    actor
  );

  return to_jsonb(payment_record);
end;
$function$;

CREATE OR REPLACE FUNCTION public.confirm_payment(payment_id_input bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if private.current_user_role() is distinct from 'admin' then
    raise exception 'Chỉ admin được xác nhận thanh toán trực tiếp.';
  end if;
  perform private.complete_payment(payment_id_input);
end;
$function$;

CREATE OR REPLACE FUNCTION public.confirm_payment(payment_id_input bigint, reason_input text DEFAULT 'Xác nhận thanh toán'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor public.user_roles%rowtype;
  payment_record public.payments%rowtype;
  before_record public.payments%rowtype;
  customer_record public.customers%rowtype;
  kiosk_record public.kiosks%rowtype;
  package_record public.business_types%rowtype;
  confirmation_timestamp timestamptz := now();
  confirmation_date date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
  effective_start_date date;
  calculated_end_date date;
  expected_total numeric;
begin
  actor := private.assert_payment_permission();

  select *
  into payment_record
  from public.payments
  where id = payment_id_input
  for update;

  if not found then
    raise exception 'Không tìm thấy thanh toán.';
  end if;

  if lower(payment_record.payment_status) <> 'pending' then
    raise exception 'Chỉ thanh toán Pending mới được xác nhận.';
  end if;

  if payment_record.transaction_type <> 'standard' then
    raise exception 'Giao dịch điều chỉnh không dùng confirm_payment().';
  end if;

  before_record := payment_record;

  select *
  into customer_record
  from public.customers
  where id = payment_record.customer_id
  for update;

  if not found then
    raise exception 'Khách hàng của thanh toán không tồn tại.';
  end if;

  select *
  into kiosk_record
  from public.kiosks
  where id = payment_record.kiosk_id
  for update;

  if not found then
    raise exception 'Kiosk của thanh toán không tồn tại.';
  end if;

  if kiosk_record.customer_id <> customer_record.id then
    raise exception 'Kiosk không thuộc khách hàng của thanh toán.';
  end if;

  select *
  into package_record
  from public.business_types
  where id = kiosk_record.business_type_id
    and is_active = true;

  if not found then
    raise exception 'Gói dịch vụ không tồn tại hoặc đã ngừng hoạt động.';
  end if;

  if payment_record.months is null or payment_record.months < 1 then
    raise exception 'Số tháng thanh toán không hợp lệ.';
  end if;

  if payment_record.price_per_month is null or payment_record.price_per_month < 0
    or payment_record.discount is null or payment_record.discount < 0
    or payment_record.total_amount is null or payment_record.total_amount <= 0 then
    raise exception 'Giá trị tài chính của thanh toán không hợp lệ.';
  end if;

  expected_total := payment_record.price_per_month * payment_record.months
    - payment_record.discount;

  if payment_record.total_amount <> expected_total then
    raise exception 'Tổng tiền không khớp giá, số tháng và giảm giá.';
  end if;

  if lower(kiosk_record.status) = 'active'
    and kiosk_record.end_date is not null
    and kiosk_record.end_date >= confirmation_date then
    effective_start_date := kiosk_record.end_date + 1;
  else
    effective_start_date := confirmation_date;
  end if;

  calculated_end_date := (
    effective_start_date + make_interval(months => payment_record.months)
  )::date;

  perform set_config('app.payment_workflow_action', 'confirm', true);

  update public.payments
  set
    payment_status = 'completed',
    confirmed_by = actor.user_id,
    confirmed_at = confirmation_timestamp,
    start_date = effective_start_date,
    end_date = calculated_end_date
  where id = payment_record.id
  returning * into payment_record;

  update public.kiosks
  set
    status = 'active',
    start_date = effective_start_date,
    end_date = calculated_end_date
  where id = kiosk_record.id;

  update public.customers
  set
    status = case
      when lower(coalesce(status, '')) = 'pending' then 'active'
      else status
    end,
    total_kiosks = (
      select count(*) from public.kiosks k where k.customer_id = customer_record.id
    )
  where id = customer_record.id;

  perform private.write_payment_audit(
    'confirm',
    to_jsonb(before_record),
    to_jsonb(payment_record),
    reason_input,
    actor
  );

  return jsonb_build_object(
    'payment', to_jsonb(payment_record),
    'kiosk', (
      select to_jsonb(k) from public.kiosks k where k.id = kiosk_record.id
    ),
    'customer', (
      select to_jsonb(c) from public.customers c where c.id = customer_record.id
    )
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.correct_historical_payment(payment_id_input bigint, start_date_input date, end_date_input date, months_input integer, total_amount_input numeric, reason_input text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_record public.user_profiles%rowtype;
  before_payment public.payments%rowtype;
  after_payment public.payments%rowtype;
  kiosk_record public.kiosks%rowtype;
  customer_record public.customers%rowtype;
  authoritative_end_date date;
  normalized_reason text := pg_catalog.btrim(coalesce(reason_input, ''));
  kiosk_end_date_before date;
  kiosk_end_date_after date;
begin
  if not public.is_system_admin() then
    raise exception 'Chỉ System Admin được sửa dữ liệu thanh toán lịch sử.'
      using errcode = '42501';
  end if;

  select * into actor_record
  from public.user_profiles
  where user_id = (select auth.uid())
    and status = 'active'
    and web_access_enabled
    and is_system_admin;
  if not found then
    raise exception 'Phiên System Admin không còn hiệu lực.' using errcode = '42501';
  end if;

  if payment_id_input is null or payment_id_input < 1 then
    raise exception 'Thanh toán không hợp lệ.' using errcode = '22023';
  end if;
  if start_date_input is null or end_date_input is null then
    raise exception 'Ngày bắt đầu và ngày kết thúc là bắt buộc.' using errcode = '22023';
  end if;
  if end_date_input < start_date_input then
    raise exception 'Ngày kết thúc không được trước ngày bắt đầu.' using errcode = '22023';
  end if;
  if months_input is null or months_input < 1 then
    raise exception 'Số tháng phải là số nguyên lớn hơn 0.' using errcode = '22023';
  end if;
  if total_amount_input is null or total_amount_input <= 0 then
    raise exception 'Số tiền phải lớn hơn 0.' using errcode = '22023';
  end if;
  if normalized_reason = '' then
    raise exception 'Lý do chỉnh sửa là bắt buộc.' using errcode = '22023';
  end if;
  if pg_catalog.length(normalized_reason) > 1000 then
    raise exception 'Lý do chỉnh sửa không được vượt quá 1000 ký tự.' using errcode = '22023';
  end if;

  select * into before_payment
  from public.payments
  where id = payment_id_input
  for update;
  if not found then
    raise exception 'Không tìm thấy thanh toán.' using errcode = 'P0002';
  end if;
  if pg_catalog.lower(coalesce(before_payment.payment_status, '')) <> 'completed'
    or before_payment.confirmed_at is null then
    raise exception 'Chỉ được sửa thanh toán đã hoàn thành và đã ghi nhận thời điểm xác nhận.'
      using errcode = '23514';
  end if;
  if pg_catalog.lower(coalesce(before_payment.transaction_type, 'standard')) = 'adjustment' then
    raise exception 'Không sửa trực tiếp giao dịch điều chỉnh.' using errcode = '23514';
  end if;
  if before_payment.registration_batch_id is not null then
    raise exception 'Thanh toán theo lô phải được đối soát ở cấp lô đăng ký.' using errcode = '23514';
  end if;
  if before_payment.kiosk_id is null then
    raise exception 'Thanh toán không gắn với Kiosk.' using errcode = '23514';
  end if;

  select * into kiosk_record
  from public.kiosks
  where id = before_payment.kiosk_id
  for update;
  if not found then
    raise exception 'Kiosk của thanh toán không tồn tại.' using errcode = 'P0002';
  end if;
  if kiosk_record.customer_id is distinct from before_payment.customer_id then
    raise exception 'Kiosk không thuộc khách hàng của thanh toán.' using errcode = '23514';
  end if;

  select * into customer_record
  from public.customers
  where id = before_payment.customer_id
  for update;
  if not found then
    raise exception 'Khách hàng của thanh toán không tồn tại.' using errcode = 'P0002';
  end if;

  if before_payment.start_date is not distinct from start_date_input
    and before_payment.end_date is not distinct from end_date_input
    and before_payment.months is not distinct from months_input
    and before_payment.total_amount is not distinct from total_amount_input then
    raise exception 'Dữ liệu mới không có thay đổi.' using errcode = '22023';
  end if;

  kiosk_end_date_before := kiosk_record.end_date;
  perform pg_catalog.set_config('app.payment_workflow_action', 'historical_correction', true);

  update public.payments
  set start_date = start_date_input,
      end_date = end_date_input,
      months = months_input,
      total_amount = total_amount_input
  where id = before_payment.id
  returning * into after_payment;

  -- Include both individual renewal payments and completed registration-batch
  -- item periods. This prevents an older corrected payment from shortening a
  -- Kiosk that already has a later completed service period.
  select pg_catalog.max(period_end) into authoritative_end_date
  from (
    select p.end_date as period_end
    from public.payments p
    where p.registration_batch_id is null
      and p.kiosk_id = before_payment.kiosk_id
      and pg_catalog.lower(coalesce(p.payment_status, '')) = 'completed'
      and p.confirmed_at is not null
      and pg_catalog.lower(coalesce(p.transaction_type, 'standard')) <> 'adjustment'
      and p.end_date is not null

    union all

    select i.end_date as period_end
    from public.registration_batch_items i
    join public.registration_batches b on b.id = i.batch_id
    join public.payments p on p.id = b.payment_id
    where i.kiosk_id = before_payment.kiosk_id
      and p.registration_batch_id = b.id
      and pg_catalog.lower(coalesce(p.payment_status, '')) = 'completed'
      and p.confirmed_at is not null
      and i.end_date is not null
  ) completed_periods;

  update public.kiosks k
  set end_date = case
    when k.end_date is not distinct from before_payment.end_date then authoritative_end_date
    when k.end_date is null then authoritative_end_date
    when authoritative_end_date > k.end_date then authoritative_end_date
    else k.end_date
  end
  where k.id = before_payment.kiosk_id
  returning k.end_date into kiosk_end_date_after;

  insert into public.audit_logs (
    actor_id, actor_name, actor_role, actor_type, module, entity, record_id,
    action, before, after, reason
  ) values (
    actor_record.user_id,
    coalesce(actor_record.display_name, actor_record.username, 'System Admin'),
    'system_admin',
    'staff',
    'Payment',
    'payments',
    before_payment.id::text,
    'update',
    pg_catalog.jsonb_build_object(
      'correction_type', 'historical_payment',
      'payment_id', before_payment.id,
      'kiosk_id', before_payment.kiosk_id,
      'customer_id', before_payment.customer_id,
      'start_date', before_payment.start_date,
      'end_date', before_payment.end_date,
      'months', before_payment.months,
      'total_amount', before_payment.total_amount,
      'kiosk_end_date', kiosk_end_date_before
    ),
    pg_catalog.jsonb_build_object(
      'correction_type', 'historical_payment',
      'payment_id', after_payment.id,
      'kiosk_id', after_payment.kiosk_id,
      'customer_id', after_payment.customer_id,
      'start_date', after_payment.start_date,
      'end_date', after_payment.end_date,
      'months', after_payment.months,
      'total_amount', after_payment.total_amount,
      'kiosk_end_date', kiosk_end_date_after
    ),
    normalized_reason
  );

  return pg_catalog.jsonb_build_object(
    'payment', pg_catalog.to_jsonb(after_payment),
    'kiosk', (
      select pg_catalog.to_jsonb(k)
      from public.kiosks k
      where k.id = before_payment.kiosk_id
    ),
    'audit', pg_catalog.jsonb_build_object(
      'reason', normalized_reason,
      'corrected_by', actor_record.user_id
    )
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_renewal_payment(kiosk_id_input bigint, months_input integer, discount_input numeric DEFAULT 0, discount_reason_input text DEFAULT NULL::text, note_input text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor public.user_roles%rowtype; kiosk_record public.kiosks%rowtype; package_record public.business_types%rowtype; payment_record public.payments%rowtype;
declare normalized_discount numeric:=coalesce(discount_input,0); calculated_total numeric; intent_key text; reused_value boolean:=false;
begin
  actor:=private.assert_payment_permission();
  if months_input is null or months_input<1 then raise exception 'Số tháng phải là số nguyên lớn hơn 0.' using errcode='22023'; end if;
  if normalized_discount<0 then raise exception 'Giảm giá không hợp lệ.' using errcode='22023'; end if;
  select * into kiosk_record from public.kiosks where id=kiosk_id_input for update;
  if not found then raise exception 'Không tìm thấy Kiosk.' using errcode='P0002'; end if;
  if kiosk_record.customer_id is null then raise exception 'Kiosk thiếu khách hàng.' using errcode='22023'; end if;
  select * into package_record from public.business_types where id=kiosk_record.business_type_id and is_active=true;
  if not found or package_record.price_per_month is null or package_record.price_per_month<0 then raise exception 'Gói dịch vụ không hợp lệ.' using errcode='22023'; end if;
  calculated_total:=package_record.price_per_month*months_input-normalized_discount;
  if calculated_total<0 then raise exception 'Giảm giá không được lớn hơn tạm tính.' using errcode='22023'; end if;
  if normalized_discount>0 and nullif(trim(discount_reason_input),'') is null then raise exception 'Lý do giảm giá là bắt buộc khi có giảm giá.' using errcode='22023'; end if;
  intent_key:='admin-renewal:'||kiosk_id_input::text||':'||months_input::text||':'||normalized_discount::text;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(intent_key,0));
  select * into payment_record from public.payments where payment_intent_key=intent_key and payment_status='pending' order by id desc limit 1 for update;
  if found then reused_value:=true; end if;
  if not found then
    select * into payment_record from public.payments
    where kiosk_id=kiosk_id_input and payment_status='pending' and transaction_type='standard'
      and start_date is null and end_date is null and months=months_input and discount=normalized_discount
      and total_amount=calculated_total and registration_request_id is null
      and coalesce(note,'')<>'Public PayOS Kiosk renewal'
    order by id desc limit 1 for update;
    if found then reused_value:=true; update public.payments set payment_intent_key=intent_key where id=payment_record.id returning * into payment_record; end if;
  end if;
  if not found then
    insert into public.payments(customer_id,kiosk_id,start_date,end_date,months,price_per_month,discount,discount_reason,total_amount,payment_method,payment_status,note,transaction_type,service_month_delta,payment_intent_key)
    values(kiosk_record.customer_id,kiosk_record.id,null,null,months_input,package_record.price_per_month,normalized_discount,nullif(trim(discount_reason_input),''),calculated_total,'transfer','pending',nullif(trim(note_input),''),'standard',0,intent_key)
    returning * into payment_record;
    perform private.write_payment_audit('create_renewal',null,to_jsonb(payment_record),'Tạo yêu cầu gia hạn PayOS',actor);
  end if;
  return jsonb_build_object('payment',to_jsonb(payment_record),'package',jsonb_build_object('id',package_record.id,'name',package_record.name,'pricePerMonth',package_record.price_per_month),'reused',reused_value);
end;$function$;

CREATE OR REPLACE FUNCTION public.fail_registration_payos_order(payment_id_input bigint, order_code_input bigint, failure_stage_input text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare changed integer;
begin
  if coalesce(auth.jwt()->>'role', '') <> 'service_role' then
    raise exception 'Chỉ API server được cập nhật PayOS order đăng ký.' using errcode = '42501';
  end if;
  update public.payos_orders o set status = 'failed', active_slot = null,
    error = left(coalesce(failure_stage_input, 'PAYOS_FAILURE'), 100),
    processed_at = coalesce(o.processed_at, pg_catalog.now()), updated_at = pg_catalog.now()
  where o.payment_id = payment_id_input and o.order_code = order_code_input
    and o.purpose = 'crm_payment' and o.status = 'pending' and o.active_slot is true
    and o.checkout_url is null and exists (select 1 from public.payments p
      where p.id = o.payment_id and p.payment_status = 'pending');
  get diagnostics changed = row_count;
  return changed = 1;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_audit_log(log_id_input bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  result jsonb;
begin
  perform private.assert_audit_access();
  select to_jsonb(r)
  into result
  from (
    select
      al.id,
      al.actor_id,
      case
        when al.actor_id is not null then coalesce(ur.display_name, ur.username, al.actor_name, 'Nhân viên')
        when coalesce(al.actor_type, lower(al.actor_role)) in ('public', 'anon') then 'Public User'
        when al.actor_type = 'database_trigger' then 'Database Trigger'
        else 'System'
      end as actor_name,
      coalesce(
        al.actor_type,
        case
          when al.actor_id is not null then 'staff'
          when lower(al.actor_role) in ('public', 'anon') then 'public'
          else 'system'
        end
      ) as actor_type,
      coalesce(ur.role, al.actor_role, 'system') as actor_role,
      al.module,
      coalesce(al.entity, al.module) as entity,
      al.record_id,
      al.action,
      al.before,
      al.after,
      al.reason,
      al.created_at
    from public.audit_logs al
    left join public.user_roles ur on ur.user_id = al.actor_id
    where al.id = log_id_input
  ) r;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_audit_logs(actor_filter text DEFAULT NULL::text, module_filter text DEFAULT NULL::text, action_filter text DEFAULT NULL::text, from_time timestamp with time zone DEFAULT NULL::timestamp with time zone, to_time timestamp with time zone DEFAULT NULL::timestamp with time zone, search_term text DEFAULT NULL::text, show_technical boolean DEFAULT false, page_number integer DEFAULT 1, page_size integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  normalized_page integer := greatest(coalesce(page_number, 1), 1);
  normalized_size integer := case when page_size in (10, 20, 50) then page_size else 20 end;
  requested_category text := case pg_catalog.lower(nullif(pg_catalog.btrim(module_filter), ''))
    when 'kiosk' then 'kiosk'
    when 'kiosks' then 'kiosk'
    when 'registration' then 'kiosk'
    when 'registrations' then 'kiosk'
    when 'registration_request' then 'kiosk'
    when 'registration_requests' then 'kiosk'
    when 'registration_batch' then 'kiosk'
    when 'registration_batches' then 'kiosk'
    when 'public_registration' then 'kiosk'
    when 'public_registrations' then 'kiosk'
    when 'customer' then 'customer'
    when 'customers' then 'customer'
    when 'client' then 'customer'
    when 'clients' then 'customer'
    when 'payment' then 'payment'
    when 'payments' then 'payment'
    when 'transaction' then 'payment'
    when 'transactions' then 'payment'
    when 'payos' then 'payment'
    when 'payment_intent' then 'payment'
    when 'payment_intents' then 'payment'
    when 'payment_order' then 'payment'
    when 'payment_orders' then 'payment'
    when 'renewal' then 'renewal'
    when 'renewals' then 'renewal'
    when 'kiosk_renewal' then 'renewal'
    when 'kiosk_renewals' then 'renewal'
    when 'gia_han' then 'renewal'
    when 'usermanagement' then 'user'
    when 'user_management' then 'user'
    when 'user-management' then 'user'
    when 'user' then 'user'
    when 'users' then 'user'
    when 'user_profile' then 'user'
    when 'user_profiles' then 'user'
    when 'staff' then 'user'
    when 'staffs' then 'user'
    when 'staff_member' then 'user'
    when 'staff_members' then 'user'
    when 'personnel' then 'user'
    when 'employee' then 'user'
    when 'employees' then 'user'
    when 'permission' then 'user'
    when 'permissions' then 'user'
    when 'user_permission' then 'user'
    when 'user_permissions' then 'user'
    when 'wallet' then 'user'
    when 'wallets' then 'user'
    when 'ttc_wallet' then 'user'
    when 'ttc_wallets' then 'user'
    when 'ttc_user_wallet' then 'user'
    when 'ttc_user_wallets' then 'user'
    when 'promotion' then 'promotion'
    when 'promotions' then 'promotion'
    when 'discount' then 'promotion'
    when 'discounts' then 'promotion'
    when 'coupon' then 'promotion'
    when 'coupons' then 'promotion'
    when 'promotion_usage' then 'promotion'
    when 'promotion_usages' then 'promotion'
    when 'system' then 'system'
    when 'webhook' then 'system'
    when 'webhooks' then 'system'
    when 'cron' then 'system'
    when 'cleanup' then 'system'
    when 'sync' then 'system'
    when 'synchronization' then 'system'
    when 'trigger' then 'system'
    when 'database_trigger' then 'system'
    else pg_catalog.lower(nullif(pg_catalog.btrim(module_filter), ''))
  end;
  result jsonb;
begin
  perform private.assert_audit_access();

  with resolved as materialized (
    select
      al.id,
      al.actor_id,
      case
        when al.actor_id is not null then coalesce(ur.display_name, ur.username, al.actor_name, 'Nhân viên')
        when coalesce(al.actor_type, pg_catalog.lower(al.actor_role)) in ('public', 'anon') then 'Public User'
        when al.actor_type = 'database_trigger' then 'Database Trigger'
        else 'System'
      end as actor_name,
      coalesce(
        al.actor_type,
        case
          when al.actor_id is not null then 'staff'
          when pg_catalog.lower(al.actor_role) in ('public', 'anon') then 'public'
          else 'system'
        end
      ) as actor_type,
      coalesce(ur.role, al.actor_role, 'system') as actor_role,
      al.module,
      coalesce(al.entity, al.module) as entity,
      al.record_id,
      al.action,
      al.before,
      al.after,
      al.reason,
      al.created_at,
      pg_catalog.lower(pg_catalog.btrim(coalesce(al.module, ''))) as normalized_module,
      pg_catalog.lower(pg_catalog.btrim(coalesce(al.entity, ''))) as normalized_entity,
      pg_catalog.lower(pg_catalog.btrim(coalesce(al.action, ''))) as normalized_action
    from public.audit_logs al
    left join public.user_roles ur on ur.user_id = al.actor_id
  ),
  classified as materialized (
    select
      r.*,
      case
        when r.normalized_module = any (array['renewal','renewals','kiosk_renewal','kiosk_renewals','gia_han']::text[])
          or r.normalized_entity = any (array['renewal','renewals','kiosk_renewal','kiosk_renewals','gia_han']::text[])
          or r.normalized_action = 'admin_manual_renewal'
          or r.normalized_action like '%renewal%'
          then 'renewal'
        when r.normalized_module = any (array['promotion','promotions','discount','discounts','coupon','coupons','promotion_usage','promotion_usages']::text[])
          or r.normalized_entity = any (array['promotion','promotions','discount','discounts','coupon','coupons','promotion_usage','promotion_usages']::text[])
          or r.normalized_action like '%promotion%'
          then 'promotion'
        when r.normalized_module = any (array['payment','payments','transaction','transactions','payos','payment_intent','payment_intents','payment_order','payment_orders']::text[])
          or r.normalized_entity = any (array['payment','payments','transaction','transactions','payos','payment_intent','payment_intents','payment_order','payment_orders']::text[])
          or r.normalized_action like '%payos%'
          or r.normalized_action like '%payment%'
          or r.normalized_action like '%refund%'
          then 'payment'
        when r.normalized_module = any (array['usermanagement','user_management','user-management','user','users','user_profile','user_profiles','staff','staffs','staff_member','staff_members','personnel','employee','employees','permission','permissions','user_permission','user_permissions','wallet','wallets','ttc_wallet','ttc_wallets','ttc_user_wallet','ttc_user_wallets']::text[])
          or r.normalized_entity = any (array['usermanagement','user_management','user-management','user','users','user_profile','user_profiles','staff','staffs','staff_member','staff_members','personnel','employee','employees','permission','permissions','user_permission','user_permissions','wallet','wallets','ttc_wallet','ttc_wallets','ttc_user_wallet','ttc_user_wallets']::text[])
          or r.normalized_action = any (array['reset_password','update_profile','admin_reset_user_password','admin_update_user_profile','admin_update_user_status','sync_permissions','lock_user','unlock_user','adjust_wallet','admin_adjustment']::text[])
          then 'user'
        when r.normalized_module = any (array['customer','customers','client','clients']::text[])
          or r.normalized_entity = any (array['customer','customers','client','clients']::text[])
          then 'customer'
        when r.normalized_module = any (array['kiosk','kiosks','registration','registrations','registration_request','registration_requests','registration_batch','registration_batches','public_registration','public_registrations']::text[])
          or r.normalized_entity = any (array['kiosk','kiosks','registration','registrations','registration_request','registration_requests','registration_batch','registration_batches','public_registration','public_registrations']::text[])
          or r.normalized_action = any (array['review_legacy_approve','review_legacy_cancel','admin_cancel']::text[])
          then 'kiosk'
        else 'system'
      end as category
    from resolved r
  ),
  visible as materialized (
    select c.*
    from classified c
    where show_technical
      or (
        c.normalized_action = any (array[
          'create', 'update', 'delete', 'confirm', 'cancel', 'reject', 'approve', 'approved',
          'set_active', 'reset_password', 'update_profile', 'admin_reset_user_password',
          'admin_update_user_profile', 'admin_update_user_status', 'sync_permissions',
          'lock_user', 'unlock_user', 'adjust_wallet', 'admin_adjustment',
          'admin_manual_renewal', 'confirm_payos', 'confirm_payos_batch', 'admin_cancel',
          'review_legacy_approve', 'review_legacy_cancel', 'create_promotion',
          'update_promotion', 'pause_promotion', 'reactivate_promotion',
          'delete_promotion', 'expire', 'expired', 'activate', 'deactivate'
        ]::text[])
        and (
          c.category <> 'system'
          or c.normalized_action = any (array['expire','expired','activate','deactivate']::text[])
        )
      )
  ),
  filtered as materialized (
    select *
    from visible r
    where (nullif(pg_catalog.btrim(actor_filter), '') is null
        or r.actor_name ilike '%' || pg_catalog.btrim(actor_filter) || '%'
        or r.actor_role ilike '%' || pg_catalog.btrim(actor_filter) || '%'
        or r.actor_type ilike '%' || pg_catalog.btrim(actor_filter) || '%'
        or r.actor_id::text = pg_catalog.btrim(actor_filter))
      and (requested_category is null
        or r.category = requested_category
        or r.normalized_module = pg_catalog.lower(pg_catalog.btrim(module_filter))
        or r.normalized_entity = pg_catalog.lower(pg_catalog.btrim(module_filter)))
      and (nullif(pg_catalog.btrim(action_filter), '') is null
        or r.normalized_action = pg_catalog.lower(pg_catalog.btrim(action_filter)))
      and (from_time is null or r.created_at >= from_time)
      and (to_time is null or r.created_at < to_time)
      and (nullif(pg_catalog.btrim(search_term), '') is null
        or r.module ilike '%' || pg_catalog.btrim(search_term) || '%'
        or r.entity ilike '%' || pg_catalog.btrim(search_term) || '%'
        or r.action ilike '%' || pg_catalog.btrim(search_term) || '%'
        or r.actor_name ilike '%' || pg_catalog.btrim(search_term) || '%'
        or coalesce(r.reason, '') ilike '%' || pg_catalog.btrim(search_term) || '%'
        or coalesce(r.record_id, '') ilike '%' || pg_catalog.btrim(search_term) || '%')
  ),
  stats as (
    select pg_catalog.count(*)::integer as total from filtered
  ),
  bounds as (
    select
      total,
      least(normalized_page, greatest(1, ceil(total::numeric / normalized_size)::integer)) as effective_page
    from stats
  ),
  paged as (
    select f.*
    from filtered f
    cross join bounds b
    order by f.created_at desc, f.id desc
    limit normalized_size
    offset ((select effective_page from bounds) - 1) * normalized_size
  )
  select pg_catalog.jsonb_build_object(
    'rows', coalesce(
      (
        select pg_catalog.jsonb_agg(
          pg_catalog.to_jsonb(p) - 'normalized_module' - 'normalized_entity' - 'normalized_action'
          order by p.created_at desc, p.id desc
        )
        from paged p
      ),
      '[]'::jsonb
    ),
    'total', b.total,
    'page', b.effective_page,
    'pageSize', normalized_size
  ) into result
  from bounds b;

  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_business_types_with_stats(search_term text)
 RETURNS TABLE(id bigint, category_id bigint, name text, description text, price_per_month numeric, is_active boolean, created_at timestamp with time zone, updated_at timestamp with time zone, category_name text, kiosk_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select
    bt.id,
    bt.category_id,
    bt.name,
    bt.description,
    bt.price_per_month,
    bt.is_active,
    bt.created_at,
    bt.updated_at,
    c.name as category_name,
    coalesce(k.kiosk_count, 0) as kiosk_count
  from public.business_types bt
  left join public.categories c on bt.category_id = c.id
  left join (
    select business_type_id, count(*) as kiosk_count
    from public.kiosks
    where business_type_id is not null
    group by business_type_id
  ) k on bt.id = k.business_type_id
  where search_term is null
     or bt.name ilike ('%' || search_term || '%')
     or bt.description ilike ('%' || search_term || '%')
     or c.name ilike ('%' || search_term || '%');
$function$;

CREATE OR REPLACE FUNCTION public.get_categories_with_stats()
 RETURNS TABLE(id bigint, name text, description text, is_active boolean, created_at timestamp with time zone, updated_at timestamp with time zone, kiosk_count bigint, customer_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select
    c.id,
    c.name,
    c.description,
    c.is_active,
    c.created_at,
    c.updated_at,
    coalesce(k.kiosk_count, 0) as kiosk_count,
    coalesce(k.customer_count, 0) as customer_count
  from public.categories c
  left join (
    select
      category_id,
      count(*) as kiosk_count,
      count(distinct customer_id) as customer_count
    from public.kiosks
    where category_id is not null
    group by category_id
  ) k on c.id = k.category_id;
$function$;

CREATE OR REPLACE FUNCTION public.get_customer_status_data(p_search text DEFAULT NULL::text, p_customer_status text DEFAULT NULL::text, p_kiosk_status text DEFAULT NULL::text, p_customer_id bigint DEFAULT NULL::bigint, p_sort_by text DEFAULT 'created_at'::text, p_sort_direction text DEFAULT 'desc'::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  warning_days integer;
  today_date date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
  result jsonb;
begin
  if p_page < 1 or p_page_size not in (10, 25, 50) then raise exception 'Phân trang khách hàng không hợp lệ.'; end if;
  warning_days := public.get_status_warning_days();

  with kiosk_states as (
    select k.customer_id, k.id,
      public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) as derived_status,
      k.end_date
    from public.kiosks k
  ), classified as (
    select c.*,
      public.resolve_customer_status(c.status,
        coalesce(array_agg(ks.derived_status) filter (where ks.id is not null), '{}'::text[])) as derived_status,
      coalesce(count(ks.id), 0)::bigint as actual_total_kiosks,
      min(ks.end_date) filter (where ks.derived_status = 'warning') as nearest_warning_end_date,
      max(ks.end_date) filter (where ks.derived_status = 'expired') as latest_expired_end_date,
      coalesce(bool_or(ks.derived_status = lower(p_kiosk_status)), false) as has_requested_kiosk_status
    from public.customers c left join kiosk_states ks on ks.customer_id = c.id
    group by c.id
  ), filtered as (
    select * from classified
    where (p_customer_id is null or id = p_customer_id)
      and (p_customer_status is null or p_customer_status = '' or derived_status = lower(p_customer_status))
      and (p_kiosk_status is null or p_kiosk_status = '' or has_requested_kiosk_status)
      and (p_search is null or btrim(p_search) = '' or phone ilike '%' || btrim(p_search) || '%'
        or facebook_id ilike '%' || btrim(p_search) || '%' or facebook_name ilike '%' || btrim(p_search) || '%')
  ), counted as (select count(*)::bigint total_rows from filtered),
  groups as (
    select coalesce(jsonb_object_agg(derived_status, amount), '{}'::jsonb) data
    from (select derived_status, count(*)::bigint amount from filtered group by derived_status) grouped
  ), paged as (
    select * from filtered order by
      case when p_kiosk_status = 'warning' then nearest_warning_end_date end asc nulls last,
      case when p_kiosk_status = 'expired' then latest_expired_end_date end desc nulls last,
      case when p_sort_by = 'facebook_name' and lower(p_sort_direction) = 'asc' then facebook_name end asc,
      case when p_sort_by = 'facebook_name' and lower(p_sort_direction) = 'desc' then facebook_name end desc,
      case when p_sort_by = 'total_kiosks' and lower(p_sort_direction) = 'asc' then actual_total_kiosks end asc,
      case when p_sort_by = 'total_kiosks' and lower(p_sort_direction) = 'desc' then actual_total_kiosks end desc,
      case when coalesce(p_sort_by, 'created_at') = 'created_at' and lower(p_sort_direction) = 'asc' then created_at end asc,
      created_at desc, id desc
    limit p_page_size offset (p_page - 1) * p_page_size
  ), rows as (
    select coalesce(jsonb_agg(to_jsonb(paged) - 'has_requested_kiosk_status'
      || jsonb_build_object('stored_status', status, 'status', derived_status,
        'total_kiosks', actual_total_kiosks)), '[]'::jsonb) data from paged
  )
  select jsonb_build_object('rows', r.data, 'totalRows', c.total_rows,
    'statusCounts', g.data, 'warningDays', warning_days, 'reportDate', today_date)
  into result from rows r cross join counted c cross join groups g;
  return coalesce(result, '{}'::jsonb);
end
$function$;

CREATE OR REPLACE FUNCTION public.get_dashboard_data(p_year integer DEFAULT (EXTRACT(year FROM (now() AT TIME ZONE 'Asia/Ho_Chi_Minh'::text)))::integer, p_month integer DEFAULT (EXTRACT(month FROM (now() AT TIME ZONE 'Asia/Ho_Chi_Minh'::text)))::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  result jsonb;
  warning_days integer;
  today_date date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
  month_start timestamptz;
  next_month_start timestamptz;
  year_start timestamptz;
  next_year_start timestamptz;
begin
  if auth.uid() is null or not exists (
    select 1
    from public.user_roles ur
    where ur.user_id = auth.uid()
      and ur.is_active = true
      and (
        lower(ur.role) = 'admin'
        or exists (
          select 1
          from public.role_permissions rp
          where lower(rp.role) = lower(ur.role)
            and 'dashboard' = any(rp.permissions)
        )
      )
  ) then
    raise exception 'Không có quyền xem Dashboard.'
      using errcode = '42501';
  end if;

  if p_year is null or p_year < 1 or p_year > 9999 then
    raise exception 'Năm Dashboard không hợp lệ.';
  end if;

  if p_month is null or p_month < 1 or p_month > 12 then
    raise exception 'Tháng Dashboard không hợp lệ.';
  end if;

  select greatest(
    coalesce(case when s.value ~ '^\d+$' then s.value::integer end, 30),
    0
  )
  into warning_days
  from public.settings s
  where s.key = 'warning_days';

  warning_days := coalesce(warning_days, 30);
  month_start := make_timestamptz(p_year, p_month, 1, 0, 0, 0, 'Asia/Ho_Chi_Minh');
  next_month_start := month_start + interval '1 month';
  year_start := make_timestamptz(p_year, 1, 1, 0, 0, 0, 'Asia/Ho_Chi_Minh');
  next_year_start := year_start + interval '1 year';

  with
  customer_kpis as (
    select count(*)::bigint as total_customers
    from public.customers
  ),
  kiosk_kpis as (
    select
      count(*)::bigint as total_kiosks,
      count(*) filter (where public.resolve_kiosk_status(status, end_date, warning_days, today_date) = 'active')::bigint as active_kiosks,
      count(*) filter (where public.resolve_kiosk_status(status, end_date, warning_days, today_date) = 'pending')::bigint as pending_kiosks,
      count(*) filter (where public.resolve_kiosk_status(status, end_date, warning_days, today_date) = 'expired')::bigint as expired_kiosks,
      count(*) filter (
        where public.resolve_kiosk_status(status, end_date, warning_days, today_date) = 'warning'
      )::bigint as expiring_soon
    from public.kiosks
  ),
  revenue_kpis as (
    select
      coalesce(sum(total_amount) filter (
        where confirmed_at >= month_start
          and confirmed_at < next_month_start
      ), 0) as revenue_this_month,
      coalesce(sum(total_amount) filter (
        where confirmed_at >= year_start
          and confirmed_at < next_year_start
      ), 0) as revenue_this_year
    from public.payments
    where lower(payment_status) = 'completed'
      and confirmed_at is not null
  ),
  monthly_revenue as (
    select jsonb_agg(
      jsonb_build_object('month', month_number - 1, 'total', total)
      order by month_number
    ) as data
    from (
      select
        month_number,
        coalesce(sum(p.total_amount), 0) as total
      from generate_series(1, 12) as months(month_number)
      left join public.payments p
        on lower(p.payment_status) = 'completed'
        and p.confirmed_at is not null
        and p.confirmed_at >= make_timestamptz(p_year, month_number, 1, 0, 0, 0, 'Asia/Ho_Chi_Minh')
        and p.confirmed_at < make_timestamptz(p_year, month_number, 1, 0, 0, 0, 'Asia/Ho_Chi_Minh') + interval '1 month'
      group by month_number
    ) totals
  ),
  category_distribution as (
    select coalesce(
      jsonb_agg(
        jsonb_build_object('name', name, 'count', kiosk_count)
        order by kiosk_count desc, name
      ),
      '[]'::jsonb
    ) as data
    from (
      select
        coalesce(c.name, 'Chưa phân loại') as name,
        count(*)::bigint as kiosk_count
      from public.kiosks k
      left join public.categories c on c.id = k.category_id
      group by coalesce(c.name, 'Chưa phân loại')
    ) distribution
  ),
  expiring_kiosks as (
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', item.id,
          'facebook_name', item.facebook_name,
          'end_date', item.end_date,
          'customers', jsonb_build_object(
            'facebook_name', item.customer_name,
            'phone', item.customer_phone
          )
        )
        order by item.end_date, item.id
      ),
      '[]'::jsonb
    ) as data
    from (
      select
        k.id,
        k.facebook_name,
        k.end_date,
        c.facebook_name as customer_name,
        c.phone as customer_phone
      from public.kiosks k
      left join public.customers c on c.id = k.customer_id
      where public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) = 'warning'
      order by k.end_date, k.id
    ) item
  ),
  recent_registrations as (
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', item.id,
          'kioskName', item.kiosk_name,
          'amount', item.amount,
          'createdAt', item.created_at
        )
        order by item.created_at desc, item.id desc
      ),
      '[]'::jsonb
    ) as data
    from (
      select
        r.id,
        coalesce(nullif(k.facebook_name, ''), nullif(r.facebook_name, ''), 'Kiosk') as kiosk_name,
        case
          when bi.id is not null then bi.total_amount
          else coalesce(r.total_amount, 0)
        end as amount,
        r.submitted_at as created_at
      from public.registration_requests r
      left join public.registration_batch_items bi on bi.registration_request_id = r.id
      left join public.kiosks k on k.id = coalesce(bi.kiosk_id, r.kiosk_id)
      order by r.submitted_at desc, r.id desc
      limit 5
    ) item
  )
  select jsonb_build_object(
    'summary', jsonb_build_object(
      'totalCustomers', coalesce(c.total_customers, 0),
      'totalKiosks', coalesce(k.total_kiosks, 0),
      'activeKiosks', coalesce(k.active_kiosks, 0),
      'pendingKiosks', coalesce(k.pending_kiosks, 0),
      'expiredKiosks', coalesce(k.expired_kiosks, 0),
      'expiringSoon', coalesce(k.expiring_soon, 0),
      'revenueThisMonth', coalesce(r.revenue_this_month, 0),
      'revenueThisYear', coalesce(r.revenue_this_year, 0)
    ),
    'charts', jsonb_build_object(
      'monthlyRevenue', coalesce(m.data, '[]'::jsonb),
      'categoryDistribution', coalesce(d.data, '[]'::jsonb)
    ),
    'lists', jsonb_build_object(
      'expiringKiosks', coalesce(e.data, '[]'::jsonb),
      'recentRegistrations', coalesce(rr.data, '[]'::jsonb)
    ),
    'year', p_year,
    'month', p_month,
    'warningDays', warning_days
  )
  into result
  from customer_kpis c
  cross join kiosk_kpis k
  cross join revenue_kpis r
  cross join monthly_revenue m
  cross join category_distribution d
  cross join expiring_kiosks e
  cross join recent_registrations rr;

  return coalesce(result, '{}'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_kiosk_status_data(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_business_type_id bigint DEFAULT NULL::bigint, p_sort_by text DEFAULT 'created_at'::text, p_sort_direction text DEFAULT 'desc'::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 12)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  warning_days integer;
  today_date date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
  result jsonb;
begin
  if p_page < 1 or p_page_size not in (12, 24, 48) then
    raise exception 'Phân trang Kiosk không hợp lệ.';
  end if;
  if lower(coalesce(p_sort_direction, 'desc')) not in ('asc', 'desc') then
    raise exception 'Chiều sắp xếp không hợp lệ.';
  end if;

  warning_days := public.get_status_warning_days();

  with classified as (
    select k.*,
      public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) as derived_status,
      c.facebook_name as customer_name, c.facebook_id as customer_facebook_id,
      c.phone as customer_phone, c.address as customer_address, c.status as customer_stored_status,
      c.total_paid as customer_total_paid, c.total_kiosks as customer_total_kiosks, c.note as customer_note,
      ca.name as category_name, bt.name as business_type_name, bt.price_per_month
    from public.kiosks k
    left join public.customers c on c.id = k.customer_id
    left join public.categories ca on ca.id = k.category_id
    left join public.business_types bt on bt.id = k.business_type_id
  ), filtered as (
    select * from classified
    where (p_business_type_id is null or business_type_id = p_business_type_id)
      and (p_status is null or p_status = '' or derived_status = lower(p_status))
      and (p_search is null or btrim(p_search) = '' or
        facebook_name ilike '%' || btrim(p_search) || '%' or
        facebook_id ilike '%' || btrim(p_search) || '%' or
        derived_status ilike '%' || btrim(p_search) || '%' or
        business_type_name ilike '%' || btrim(p_search) || '%')
  ), counted as (
    select count(*)::bigint as total_rows from filtered
  ), groups as (
    select coalesce(jsonb_object_agg(derived_status, amount), '{}'::jsonb) as data
    from (select derived_status, count(*)::bigint amount from filtered group by derived_status) grouped
  ), paged as (
    select * from filtered
    order by
      case when p_sort_by = 'end_date' and lower(p_sort_direction) = 'asc' then end_date end asc nulls last,
      case when p_sort_by = 'end_date' and lower(p_sort_direction) = 'desc' then end_date end desc nulls last,
      case when p_sort_by = 'facebook_name' and lower(p_sort_direction) = 'asc' then facebook_name end asc nulls last,
      case when p_sort_by = 'facebook_name' and lower(p_sort_direction) = 'desc' then facebook_name end desc nulls last,
      case when p_sort_by = 'status' and lower(p_sort_direction) = 'asc' then derived_status end asc,
      case when p_sort_by = 'status' and lower(p_sort_direction) = 'desc' then derived_status end desc,
      case when coalesce(p_sort_by, 'created_at') = 'created_at' and lower(p_sort_direction) = 'asc' then created_at end asc,
      created_at desc, id desc
    limit p_page_size offset (p_page - 1) * p_page_size
  ), rows as (
    select coalesce(jsonb_agg(to_jsonb(paged)
      - 'derived_status' - 'customer_name' - 'customer_facebook_id' - 'customer_phone'
      - 'customer_address' - 'customer_stored_status' - 'customer_total_paid'
      - 'customer_total_kiosks' - 'customer_note' - 'category_name'
      - 'business_type_name' - 'price_per_month'
      || jsonb_build_object('status', derived_status, 'stored_status', status,
      'customers', jsonb_build_object('id', customer_id, 'facebook_name', customer_name,
        'facebook_id', customer_facebook_id, 'phone', customer_phone, 'address', customer_address,
        'status', customer_stored_status, 'total_paid', customer_total_paid,
        'total_kiosks', customer_total_kiosks, 'note', customer_note),
      'categories', jsonb_build_object('name', category_name),
      'business_types', jsonb_build_object('name', business_type_name, 'price_per_month', price_per_month)
    ) order by case when p_status = 'warning' then end_date end asc nulls last, id desc), '[]'::jsonb) as data
    from paged
  )
  select jsonb_build_object('rows', r.data, 'totalRows', c.total_rows,
    'statusCounts', g.data, 'warningDays', warning_days, 'reportDate', today_date)
  into result from rows r cross join counted c cross join groups g;
  return coalesce(result, '{}'::jsonb);
end
$function$;

CREATE OR REPLACE FUNCTION public.get_monthly_revenue()
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select coalesce(sum(total_amount),0)
  from public.payments
  where payment_status = 'completed'
    and date_trunc('month',confirmed_at at time zone 'Europe/Berlin')
      = date_trunc('month',now() at time zone 'Europe/Berlin');
$function$;

CREATE OR REPLACE FUNCTION public.get_payment_summary(search_input text DEFAULT NULL::text, status_input text DEFAULT NULL::text, payment_method_input text DEFAULT NULL::text, business_type_id_input bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor public.user_roles%rowtype;
  month_start timestamptz := date_trunc(
    'month',
    now() at time zone 'Asia/Ho_Chi_Minh'
  ) at time zone 'Asia/Ho_Chi_Minh';
  next_month_start timestamptz;
  result jsonb;
begin
  actor := private.assert_payment_permission();
  next_month_start := month_start + interval '1 month';

  select jsonb_build_object(
    'totalRevenue', coalesce(sum(p.total_amount) filter (
      where lower(p.payment_status) = 'completed'
        and p.confirmed_at is not null
    ), 0),
    'monthRevenue', coalesce(sum(p.total_amount) filter (
      where lower(p.payment_status) = 'completed'
        and p.confirmed_at is not null
        and p.confirmed_at >= month_start
        and p.confirmed_at < next_month_start
    ), 0),
    'transferRevenue', coalesce(sum(p.total_amount) filter (
      where lower(p.payment_status) = 'completed'
        and p.confirmed_at is not null
        and lower(coalesce(p.payment_method, '')) in (
          'transfer', 'bank_transfer', 'chuyen_khoan', 'chuyển khoản'
        )
    ), 0),
    'pendingCount', count(*) filter (
      where lower(p.payment_status) = 'pending'
    )
  )
  into result
  from public.payments p
  left join public.customers c on c.id = p.customer_id
  left join public.kiosks k on k.id = p.kiosk_id
  left join public.business_types bt on bt.id = k.business_type_id
  where (status_input is null or lower(p.payment_status) = lower(status_input))
    and (payment_method_input is null or lower(p.payment_method) = lower(payment_method_input))
    and (business_type_id_input is null or k.business_type_id = business_type_id_input)
    and (
      nullif(trim(search_input), '') is null
      or p.payment_status ilike '%' || trim(search_input) || '%'
      or coalesce(p.payment_method, '') ilike '%' || trim(search_input) || '%'
      or coalesce(p.discount_reason, '') ilike '%' || trim(search_input) || '%'
      or coalesce(p.note, '') ilike '%' || trim(search_input) || '%'
      or coalesce(c.facebook_name, '') ilike '%' || trim(search_input) || '%'
      or coalesce(c.facebook_id, '') ilike '%' || trim(search_input) || '%'
      or coalesce(c.phone, '') ilike '%' || trim(search_input) || '%'
      or coalesce(k.facebook_name, '') ilike '%' || trim(search_input) || '%'
      or coalesce(k.facebook_id, '') ilike '%' || trim(search_input) || '%'
      or coalesce(bt.name, '') ilike '%' || trim(search_input) || '%'
    );

  return coalesce(result, jsonb_build_object(
    'totalRevenue', 0,
    'monthRevenue', 0,
    'transferRevenue', 0,
    'pendingCount', 0
  ));
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_registration_operations_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or not exists (
    select 1 from public.user_roles ur
    where ur.user_id = auth.uid()
      and pg_catalog.lower(ur.role) = 'admin'
      and ur.is_active
  ) then
    raise exception 'Bạn không có quyền xem tổng hợp đăng ký.' using errcode = '42501';
  end if;
  return pg_catalog.jsonb_build_object(
    'pendingPayments', (select pg_catalog.count(*) from public.payments p where p.payment_status = 'pending'),
    'awaitingPaymentRequests', (select pg_catalog.count(*) from public.registration_requests r where r.status = 'awaiting_payment'),
    'pendingKiosks', (select pg_catalog.count(*) from public.kiosks k where k.status = 'pending'),
    'pendingReviewRequests', (select pg_catalog.count(*) from public.registration_requests r where r.status = 'pending')
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_reports_data(p_report_type text DEFAULT 'overview'::text, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_customer_id bigint DEFAULT NULL::bigint, p_kiosk_id bigint DEFAULT NULL::bigint, p_category_id bigint DEFAULT NULL::bigint, p_business_type_id bigint DEFAULT NULL::bigint, p_payment_status text DEFAULT NULL::text, p_kiosk_status text DEFAULT NULL::text, p_sort_by text DEFAULT NULL::text, p_sort_direction text DEFAULT 'desc'::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  report_type text := lower(coalesce(p_report_type, ''));
  sort_direction text := lower(coalesce(p_sort_direction, 'desc'));
  warning_days integer;
  today_date date := (now() at time zone 'Asia/Ho_Chi_Minh')::date;
  start_at timestamptz;
  end_at timestamptz;
  row_offset integer;
  result jsonb;
begin
  if auth.uid() is null or not exists (
    select 1
    from public.user_roles ur
    where ur.user_id = auth.uid()
      and ur.is_active = true
      and (
        lower(ur.role) = 'admin'
        or exists (
          select 1
          from public.role_permissions rp
          where lower(rp.role) = lower(ur.role)
            and 'reports' = any(rp.permissions)
        )
      )
  ) then
    raise exception 'Không có quyền xem Báo cáo.'
      using errcode = '42501';
  end if;

  if report_type not in (
    'overview', 'revenue', 'kiosks', 'customers', 'reconciliation', 'categories'
  ) then
    raise exception 'Loại báo cáo không hợp lệ.';
  end if;

  if p_page is null or p_page < 1 then
    raise exception 'Trang báo cáo không hợp lệ.';
  end if;

  if p_page_size is null or p_page_size not in (25, 50, 100) then
    raise exception 'Kích thước trang phải là 25, 50 hoặc 100.';
  end if;

  if sort_direction not in ('asc', 'desc') then
    raise exception 'Chiều sắp xếp không hợp lệ.';
  end if;

  if p_start_date is not null and p_end_date is not null and p_start_date > p_end_date then
    raise exception 'Ngày bắt đầu phải trước hoặc bằng ngày kết thúc.';
  end if;

  select case
    when s.value ~ '^\d+$' and s.value::integer > 0 then s.value::integer
    else 30
  end
  into warning_days
  from public.settings s
  where s.key = 'warning_days';

  warning_days := coalesce(warning_days, 30);
  start_at := case
    when p_start_date is null then null
    else p_start_date::timestamp at time zone 'Asia/Ho_Chi_Minh'
  end;
  end_at := case
    when p_end_date is null then null
    else (p_end_date + 1)::timestamp at time zone 'Asia/Ho_Chi_Minh'
  end;
  row_offset := (p_page - 1) * p_page_size;

  if report_type = 'overview' then
    with
    eligible_payments as (
      select p.*
      from public.payments p
      left join public.kiosks k on k.id = p.kiosk_id
      where lower(p.payment_status) = 'completed'
        and p.confirmed_at is not null
        and (start_at is null or p.confirmed_at >= start_at)
        and (end_at is null or p.confirmed_at < end_at)
        and (p_customer_id is null or p.customer_id = p_customer_id)
        and (p_kiosk_id is null or p.kiosk_id = p_kiosk_id)
        and (p_category_id is null or k.category_id = p_category_id)
        and (p_business_type_id is null or k.business_type_id = p_business_type_id)
        and (p_payment_status is null or lower(p.payment_status) = lower(p_payment_status))
        and (p_kiosk_status is null or public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) = case when lower(p_kiosk_status) = 'expiring_soon' then 'warning' else lower(p_kiosk_status) end)
    ),
    operational_payments as (
      select p.*
      from public.payments p
      left join public.kiosks k on k.id = p.kiosk_id
      where (
          (lower(p.payment_status) = 'completed' and p.confirmed_at is not null
            and (start_at is null or p.confirmed_at >= start_at)
            and (end_at is null or p.confirmed_at < end_at))
          or
          (lower(p.payment_status) <> 'completed'
            and (start_at is null or p.created_at >= start_at)
            and (end_at is null or p.created_at < end_at))
        )
        and (p_customer_id is null or p.customer_id = p_customer_id)
        and (p_kiosk_id is null or p.kiosk_id = p_kiosk_id)
        and (p_category_id is null or k.category_id = p_category_id)
        and (p_business_type_id is null or k.business_type_id = p_business_type_id)
        and (p_payment_status is null or lower(p.payment_status) = lower(p_payment_status))
        and (p_kiosk_status is null or public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) = case when lower(p_kiosk_status) = 'expiring_soon' then 'warning' else lower(p_kiosk_status) end)
    ),
    filtered_kiosks as (
      select k.*
      from public.kiosks k
      where (p_customer_id is null or k.customer_id = p_customer_id)
        and (p_kiosk_id is null or k.id = p_kiosk_id)
        and (p_category_id is null or k.category_id = p_category_id)
        and (p_business_type_id is null or k.business_type_id = p_business_type_id)
        and (
          p_kiosk_status is null
          or (lower(p_kiosk_status) = 'expiring_soon'
            and public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) = 'warning')
          or public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) = case when lower(p_kiosk_status) = 'expiring_soon' then 'warning' else lower(p_kiosk_status) end
        )
    ),
    payment_summary as (
      select
        coalesce(sum(total_amount), 0) as total_revenue,
        count(*)::bigint as completed_count
      from eligible_payments
    ),
    operational_summary as (
      select
        count(*) filter (where lower(payment_status) = 'pending')::bigint as pending_count,
        coalesce(sum(total_amount) filter (where lower(payment_status) = 'pending'), 0) as pending_amount,
        count(*) filter (where lower(payment_status) = 'rejected')::bigint as rejected_count,
        count(*) filter (where lower(payment_status) = 'cancelled')::bigint as cancelled_count
      from operational_payments
    ),
    kiosk_summary as (
      select
        count(*)::bigint as total_kiosks,
        count(*) filter (where public.resolve_kiosk_status(status, end_date, warning_days, today_date) = 'active')::bigint as active_kiosks,
        count(*) filter (where public.resolve_kiosk_status(status, end_date, warning_days, today_date) = 'pending')::bigint as pending_kiosks,
        count(*) filter (where public.resolve_kiosk_status(status, end_date, warning_days, today_date) = 'expired')::bigint as expired_kiosks,
        count(*) filter (where public.resolve_kiosk_status(status, end_date, warning_days, today_date) = 'suspended')::bigint as suspended_kiosks,
        count(*) filter (
          where public.resolve_kiosk_status(status, end_date, warning_days, today_date) = 'warning'
        )::bigint as expiring_soon
      from filtered_kiosks
    ),
    top_customers as (
      select coalesce(jsonb_agg(to_jsonb(item) order by item."totalAmount" desc), '[]'::jsonb) as data
      from (
        select
          p.customer_id as "customerId",
          coalesce(c.facebook_name, 'Không tên') as "customerName",
          coalesce(c.phone, '') as phone,
          count(*)::bigint as "paymentCount",
          coalesce(sum(p.total_amount), 0) as "totalAmount"
        from eligible_payments p
        left join public.customers c on c.id = p.customer_id
        group by p.customer_id, c.facebook_name, c.phone
        order by "totalAmount" desc, "customerId"
        limit 10
      ) item
    ),
    priority_kiosks as (
      select coalesce(jsonb_agg(to_jsonb(item) order by item."sortPriority", item."daysLeft"), '[]'::jsonb) as data
      from (
        select
          k.id,
          coalesce(k.facebook_name, 'Không tên') as "facebookName",
          coalesce(c.facebook_name, '') as "customerName",
          k.end_date as "endDate",
          case
            when public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) = 'pending' then 'pending'
            when public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) = 'expired' then 'expired'
            when public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) = 'warning' then 'warning'
            else lower(coalesce(k.status, 'unknown'))
          end as "derivedStatus",
          k.end_date - today_date as "daysLeft",
          case
            when public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) = 'pending' then 0
            when public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) = 'expired' then 1
            else 2
          end as "sortPriority"
        from filtered_kiosks k
        left join public.customers c on c.id = k.customer_id
        where lower(k.status) in ('pending', 'expired')
          or (public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) = 'warning')
        order by "sortPriority", "daysLeft" nulls last, k.id
        limit 10
      ) item
    )
    select jsonb_build_object(
      'tab', report_type,
      'generatedAt', now(),
      'summary', jsonb_build_object(
        'totalRevenue', coalesce(ps.total_revenue, 0),
        'completedCount', coalesce(ps.completed_count, 0),
        'pendingCount', coalesce(os.pending_count, 0),
        'pendingAmount', coalesce(os.pending_amount, 0),
        'rejectedCount', coalesce(os.rejected_count, 0),
        'cancelledCount', coalesce(os.cancelled_count, 0),
        'totalKiosks', coalesce(ks.total_kiosks, 0),
        'activeKiosks', coalesce(ks.active_kiosks, 0),
        'pendingKiosks', coalesce(ks.pending_kiosks, 0),
        'expiredKiosks', coalesce(ks.expired_kiosks, 0),
        'suspendedKiosks', coalesce(ks.suspended_kiosks, 0),
        'expiringSoon', coalesce(ks.expiring_soon, 0)
      ),
      'topCustomers', tc.data,
      'priorityKiosks', pk.data,
      'rows', '[]'::jsonb,
      'pagination', jsonb_build_object(
        'page', p_page, 'pageSize', p_page_size, 'totalRows', 0, 'totalPages', 0
      )
    )
    into result
    from payment_summary ps
    cross join operational_summary os
    cross join kiosk_summary ks
    cross join top_customers tc
    cross join priority_kiosks pk;

  elsif report_type = 'revenue' then
    with
    filtered as (
      select
        p.id,
        p.customer_id,
        p.kiosk_id,
        p.confirmed_at,
        p.total_amount,
        p.payment_method,
        c.facebook_name as customer_name,
        k.facebook_name as kiosk_name,
        k.category_id,
        k.business_type_id,
        ca.name as category_name,
        bt.name as business_type_name
      from public.payments p
      left join public.customers c on c.id = p.customer_id
      left join public.kiosks k on k.id = p.kiosk_id
      left join public.categories ca on ca.id = k.category_id
      left join public.business_types bt on bt.id = k.business_type_id
      where lower(p.payment_status) = 'completed'
        and p.confirmed_at is not null
        and (start_at is null or p.confirmed_at >= start_at)
        and (end_at is null or p.confirmed_at < end_at)
        and (p_customer_id is null or p.customer_id = p_customer_id)
        and (p_kiosk_id is null or p.kiosk_id = p_kiosk_id)
        and (p_category_id is null or k.category_id = p_category_id)
        and (p_business_type_id is null or k.business_type_id = p_business_type_id)
        and (p_payment_status is null or lower(p.payment_status) = lower(p_payment_status))
        and (p_kiosk_status is null or public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) = case when lower(p_kiosk_status) = 'expiring_soon' then 'warning' else lower(p_kiosk_status) end)
    ),
    summary as (
      select
        coalesce(sum(total_amount), 0) as total_revenue,
        count(*)::bigint as completed_count,
        coalesce(avg(total_amount), 0) as average_payment,
        coalesce(max(total_amount), 0) as highest_payment,
        coalesce(min(total_amount), 0) as lowest_payment
      from filtered
    ),
    monthly as (
      select coalesce(jsonb_agg(to_jsonb(item) order by item.key), '[]'::jsonb) as data
      from (
        select
          to_char(confirmed_at at time zone 'Asia/Ho_Chi_Minh', 'YYYY-MM') as key,
          'Tháng ' || to_char(confirmed_at at time zone 'Asia/Ho_Chi_Minh', 'MM/YYYY') as label,
          count(*)::bigint as "paymentCount",
          coalesce(sum(total_amount), 0) as "totalAmount"
        from filtered
        group by 1, 2
        order by 1
      ) item
    ),
    business_types as (
      select coalesce(jsonb_agg(to_jsonb(item) order by item."totalAmount" desc), '[]'::jsonb) as data
      from (
        select
          coalesce(business_type_id, 0) as "businessTypeId",
          coalesce(business_type_name, 'Chưa phân loại') as "businessTypeName",
          coalesce(category_name, 'Chưa phân loại') as "categoryName",
          count(*)::bigint as "paymentCount",
          coalesce(sum(total_amount), 0) as "totalAmount"
        from filtered
        group by business_type_id, business_type_name, category_name
      ) item
    ),
    methods as (
      select coalesce(jsonb_agg(to_jsonb(item) order by item."totalAmount" desc), '[]'::jsonb) as data
      from (
        select
          coalesce(payment_method, 'unknown') as "paymentMethod",
          count(*)::bigint as "paymentCount",
          coalesce(sum(total_amount), 0) as "totalAmount"
        from filtered
        group by payment_method
      ) item
    ),
    counted as (
      select count(*)::bigint as total_rows from filtered
    ),
    paged as (
      select *,
        row_number() over (order by
          case when p_sort_by = 'amount' and sort_direction = 'asc' then total_amount end asc nulls last,
          case when p_sort_by = 'amount' and sort_direction = 'desc' then total_amount end desc nulls last,
          case when p_sort_by = 'customer' and sort_direction = 'asc' then customer_name end asc nulls last,
          case when p_sort_by = 'customer' and sort_direction = 'desc' then customer_name end desc nulls last,
          case when p_sort_by = 'kiosk' and sort_direction = 'asc' then kiosk_name end asc nulls last,
          case when p_sort_by = 'kiosk' and sort_direction = 'desc' then kiosk_name end desc nulls last,
          case when coalesce(p_sort_by, 'confirmed_at') = 'confirmed_at' and sort_direction = 'asc' then confirmed_at end asc nulls last,
          confirmed_at desc nulls last,
          id desc
        ) as result_order
      from filtered
      order by
        case when p_sort_by = 'amount' and sort_direction = 'asc' then total_amount end asc nulls last,
        case when p_sort_by = 'amount' and sort_direction = 'desc' then total_amount end desc nulls last,
        case when p_sort_by = 'customer' and sort_direction = 'asc' then customer_name end asc nulls last,
        case when p_sort_by = 'customer' and sort_direction = 'desc' then customer_name end desc nulls last,
        case when p_sort_by = 'kiosk' and sort_direction = 'asc' then kiosk_name end asc nulls last,
        case when p_sort_by = 'kiosk' and sort_direction = 'desc' then kiosk_name end desc nulls last,
        case when coalesce(p_sort_by, 'confirmed_at') = 'confirmed_at' and sort_direction = 'asc' then confirmed_at end asc nulls last,
        confirmed_at desc nulls last,
        id desc
      limit p_page_size offset row_offset
    ),
    rows as (
      select coalesce(jsonb_agg(
        jsonb_build_object(
          'id', id,
          'customerId', customer_id,
          'customerName', coalesce(customer_name, 'Không tên'),
          'kioskId', kiosk_id,
          'kioskName', coalesce(kiosk_name, 'Không tên'),
          'categoryName', coalesce(category_name, 'Chưa phân loại'),
          'businessTypeName', coalesce(business_type_name, 'Chưa phân loại'),
          'confirmedAt', confirmed_at,
          'paymentMethod', coalesce(payment_method, 'unknown'),
          'totalAmount', coalesce(total_amount, 0)
        )
        order by result_order
      ), '[]'::jsonb) as data
      from paged
    )
    select jsonb_build_object(
      'tab', report_type,
      'generatedAt', now(),
      'summary', jsonb_build_object(
        'totalRevenue', coalesce(s.total_revenue, 0),
        'completedCount', coalesce(s.completed_count, 0),
        'averagePayment', coalesce(s.average_payment, 0),
        'highestPayment', coalesce(s.highest_payment, 0),
        'lowestPayment', coalesce(s.lowest_payment, 0)
      ),
      'groups', jsonb_build_object(
        'monthly', m.data,
        'businessTypes', bt.data,
        'paymentMethods', pm.data
      ),
      'rows', r.data,
      'pagination', jsonb_build_object(
        'page', p_page,
        'pageSize', p_page_size,
        'totalRows', c.total_rows,
        'totalPages', case when c.total_rows = 0 then 0 else ceil(c.total_rows::numeric / p_page_size)::integer end
      )
    )
    into result
    from summary s
    cross join monthly m
    cross join business_types bt
    cross join methods pm
    cross join counted c
    cross join rows r;

  elsif report_type = 'kiosks' then
    with
    filtered as (
      select
        k.id,
        k.customer_id,
        k.facebook_name,
        k.facebook_id,
        k.start_date,
        k.end_date,
        public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) as status,
        coalesce(k.total_paid, 0) as total_paid,
        c.facebook_name as customer_name,
        c.phone,
        ca.name as category_name,
        bt.name as business_type_name,
        case
          when public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) = 'warning' then true
          else false
        end as expiring_soon,
        k.end_date - today_date as days_left
      from public.kiosks k
      left join public.customers c on c.id = k.customer_id
      left join public.categories ca on ca.id = k.category_id
      left join public.business_types bt on bt.id = k.business_type_id
      where (p_customer_id is null or k.customer_id = p_customer_id)
        and (p_kiosk_id is null or k.id = p_kiosk_id)
        and (p_category_id is null or k.category_id = p_category_id)
        and (p_business_type_id is null or k.business_type_id = p_business_type_id)
        and (
          p_kiosk_status is null
          or (lower(p_kiosk_status) = 'expiring_soon'
            and public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) = 'warning')
          or public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) = case when lower(p_kiosk_status) = 'expiring_soon' then 'warning' else lower(p_kiosk_status) end
        )
    ),
    summary as (
      select
        count(*)::bigint as total_kiosks,
        count(*) filter (where status = 'active')::bigint as active_kiosks,
        count(*) filter (where status = 'pending')::bigint as pending_kiosks,
        count(*) filter (where status = 'expired')::bigint as expired_kiosks,
        count(*) filter (where status = 'suspended')::bigint as suspended_kiosks,
        count(*) filter (where expiring_soon)::bigint as expiring_soon
      from filtered
    ),
    statuses as (
      select coalesce(jsonb_agg(to_jsonb(item) order by item."kioskCount" desc), '[]'::jsonb) as data
      from (
        select
          case when expiring_soon then 'warning' else status end as status,
          count(*)::bigint as "kioskCount",
          coalesce(sum(total_paid), 0) as "totalPaid"
        from filtered
        group by case when expiring_soon then 'warning' else status end
      ) item
    ),
    counted as (
      select count(*)::bigint as total_rows from filtered
    ),
    paged as (
      select *,
        row_number() over (order by
          case when p_sort_by = 'name' and sort_direction = 'asc' then facebook_name end asc nulls last,
          case when p_sort_by = 'name' and sort_direction = 'desc' then facebook_name end desc nulls last,
          case when p_sort_by = 'status' and sort_direction = 'asc' then status end asc nulls last,
          case when p_sort_by = 'status' and sort_direction = 'desc' then status end desc nulls last,
          case when coalesce(p_sort_by, 'end_date') = 'end_date' and sort_direction = 'asc' then end_date end asc nulls last,
          end_date desc nulls last,
          id desc
        ) as result_order
      from filtered
      order by
        case when p_sort_by = 'name' and sort_direction = 'asc' then facebook_name end asc nulls last,
        case when p_sort_by = 'name' and sort_direction = 'desc' then facebook_name end desc nulls last,
        case when p_sort_by = 'status' and sort_direction = 'asc' then status end asc nulls last,
        case when p_sort_by = 'status' and sort_direction = 'desc' then status end desc nulls last,
        case when coalesce(p_sort_by, 'end_date') = 'end_date' and sort_direction = 'asc' then end_date end asc nulls last,
        end_date desc nulls last,
        id desc
      limit p_page_size offset row_offset
    ),
    rows as (
      select coalesce(jsonb_agg(
        jsonb_build_object(
          'id', id,
          'facebookName', coalesce(facebook_name, 'Không tên'),
          'facebookId', coalesce(facebook_id, ''),
          'customerId', customer_id,
          'customerName', coalesce(customer_name, ''),
          'phone', coalesce(phone, ''),
          'categoryName', coalesce(category_name, 'Chưa phân loại'),
          'businessTypeName', coalesce(business_type_name, 'Chưa phân loại'),
          'status', status,
          'derivedStatus', case when expiring_soon then 'warning' else status end,
          'startDate', start_date,
          'endDate', end_date,
          'daysLeft', days_left,
          'totalPaid', total_paid
        )
        order by result_order
      ), '[]'::jsonb) as data
      from paged
    )
    select jsonb_build_object(
      'tab', report_type,
      'generatedAt', now(),
      'summary', jsonb_build_object(
        'totalKiosks', coalesce(s.total_kiosks, 0),
        'activeKiosks', coalesce(s.active_kiosks, 0),
        'pendingKiosks', coalesce(s.pending_kiosks, 0),
        'expiredKiosks', coalesce(s.expired_kiosks, 0),
        'suspendedKiosks', coalesce(s.suspended_kiosks, 0),
        'expiringSoon', coalesce(s.expiring_soon, 0)
      ),
      'groups', jsonb_build_object('kioskStatuses', st.data),
      'rows', r.data,
      'pagination', jsonb_build_object(
        'page', p_page,
        'pageSize', p_page_size,
        'totalRows', c.total_rows,
        'totalPages', case when c.total_rows = 0 then 0 else ceil(c.total_rows::numeric / p_page_size)::integer end
      )
    )
    into result
    from summary s
    cross join statuses st
    cross join counted c
    cross join rows r;

  elsif report_type = 'customers' then
    with
    filtered as (
      select
        c.id,
        c.facebook_name,
        c.phone,
        c.status,
        coalesce(ka.total_kiosks, 0) as total_kiosks,
        coalesce(ka.active_kiosks, 0) as active_kiosks,
        coalesce(ka.expired_kiosks, 0) as expired_kiosks, public.resolve_customer_status(c.status, coalesce(ka.kiosk_statuses, '{}'::text[])) as derived_status,
        coalesce(pa.total_paid, 0) as total_paid,
        pa.latest_completed_payment,
        ka.latest_kiosk_end_date
      from public.customers c
      left join lateral (
        select
          count(*)::bigint as total_kiosks,
          count(*) filter (where public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) = 'active')::bigint as active_kiosks,
          count(*) filter (where public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) = 'expired')::bigint as expired_kiosks, array_agg(public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date)) filter (where k.id is not null) as kiosk_statuses, max(k.end_date) as latest_kiosk_end_date
        from public.kiosks k
        where k.customer_id = c.id
          and (p_kiosk_id is null or k.id = p_kiosk_id)
          and (p_category_id is null or k.category_id = p_category_id)
          and (p_business_type_id is null or k.business_type_id = p_business_type_id)
          and (
            p_kiosk_status is null
            or (lower(p_kiosk_status) = 'expiring_soon'
              and public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) = 'warning')
            or public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) = case when lower(p_kiosk_status) = 'expiring_soon' then 'warning' else lower(p_kiosk_status) end
          )
      ) ka on true
      left join lateral (
        select
          coalesce(sum(p.total_amount), 0) as total_paid,
          max(p.confirmed_at) as latest_completed_payment
        from public.payments p
        left join public.kiosks pk on pk.id = p.kiosk_id
        where p.customer_id = c.id
          and lower(p.payment_status) = 'completed'
          and p.confirmed_at is not null
          and (start_at is null or p.confirmed_at >= start_at)
          and (end_at is null or p.confirmed_at < end_at)
          and (p_kiosk_id is null or p.kiosk_id = p_kiosk_id)
          and (p_category_id is null or pk.category_id = p_category_id)
          and (p_business_type_id is null or pk.business_type_id = p_business_type_id)
          and (p_payment_status is null or lower(p.payment_status) = lower(p_payment_status))
      ) pa on true
      where (p_customer_id is null or c.id = p_customer_id)
        and (
          (p_kiosk_id is null and p_category_id is null and p_business_type_id is null and p_kiosk_status is null)
          or coalesce(ka.total_kiosks, 0) > 0
        )
    ),
    summary as (
      select
        count(*)::bigint as total_customers,
        coalesce(sum(total_kiosks), 0) as total_kiosks,
        coalesce(sum(active_kiosks), 0) as active_kiosks,
        coalesce(sum(expired_kiosks), 0) as expired_kiosks,
        coalesce(sum(total_paid), 0) as total_paid
      from filtered
    ),
    counted as (
      select count(*)::bigint as total_rows from filtered
    ),
    paged as (
      select *,
        row_number() over (order by
          case when p_sort_by = 'name' and sort_direction = 'asc' then facebook_name end asc nulls last,
          case when p_sort_by = 'name' and sort_direction = 'desc' then facebook_name end desc nulls last,
          case when p_sort_by = 'total_kiosks' and sort_direction = 'asc' then total_kiosks end asc,
          case when p_sort_by = 'total_kiosks' and sort_direction = 'desc' then total_kiosks end desc,
          case when coalesce(p_sort_by, 'total_paid') = 'total_paid' and sort_direction = 'asc' then total_paid end asc,
          total_paid desc,
          id desc
        ) as result_order
      from filtered
      order by
        case when p_sort_by = 'name' and sort_direction = 'asc' then facebook_name end asc nulls last,
        case when p_sort_by = 'name' and sort_direction = 'desc' then facebook_name end desc nulls last,
        case when p_sort_by = 'total_kiosks' and sort_direction = 'asc' then total_kiosks end asc,
        case when p_sort_by = 'total_kiosks' and sort_direction = 'desc' then total_kiosks end desc,
        case when coalesce(p_sort_by, 'total_paid') = 'total_paid' and sort_direction = 'asc' then total_paid end asc,
        total_paid desc,
        id desc
      limit p_page_size offset row_offset
    ),
    rows as (
      select coalesce(jsonb_agg(
        jsonb_build_object(
          'id', id,
          'customerName', coalesce(facebook_name, 'Không tên'),
          'phone', coalesce(phone, ''),
          'status', derived_status, 'storedStatus', lower(coalesce(status, 'unknown')),
          'totalKiosks', total_kiosks,
          'activeKiosks', active_kiosks,
          'expiredKiosks', expired_kiosks,
          'totalPaid', total_paid,
          'latestCompletedPayment', latest_completed_payment,
          'latestKioskEndDate', latest_kiosk_end_date
        )
        order by result_order
      ), '[]'::jsonb) as data
      from paged
    )
    select jsonb_build_object(
      'tab', report_type,
      'generatedAt', now(),
      'summary', jsonb_build_object(
        'totalCustomers', coalesce(s.total_customers, 0),
        'totalKiosks', coalesce(s.total_kiosks, 0),
        'activeKiosks', coalesce(s.active_kiosks, 0),
        'expiredKiosks', coalesce(s.expired_kiosks, 0),
        'totalPaid', coalesce(s.total_paid, 0)
      ),
      'rows', r.data,
      'pagination', jsonb_build_object(
        'page', p_page,
        'pageSize', p_page_size,
        'totalRows', c.total_rows,
        'totalPages', case when c.total_rows = 0 then 0 else ceil(c.total_rows::numeric / p_page_size)::integer end
      )
    )
    into result
    from summary s
    cross join counted c
    cross join rows r;

  elsif report_type = 'reconciliation' then
    with
    actual_customer_totals as (
      select
        c.id,
        count(k.id)::bigint as actual_kiosks,
        coalesce((
          select sum(p.total_amount)
          from public.payments p
          where p.customer_id = c.id
            and lower(p.payment_status) = 'completed'
            and p.confirmed_at is not null
        ), 0) as actual_paid
      from public.customers c
      left join public.kiosks k on k.customer_id = c.id
      group by c.id
    ),
    duplicate_kiosk_ids as (
      select trim(facebook_id) as facebook_id
      from public.kiosks
      where nullif(trim(facebook_id), '') is not null
      group by trim(facebook_id)
      having count(*) > 1
    ),
    duplicate_requests as (
      select trim(facebook_id) as facebook_id
      from public.registration_requests
      where lower(status) = 'pending'
        and nullif(trim(facebook_id), '') is not null
      group by trim(facebook_id)
      having count(*) > 1
    ),
    issues as (
      select
        'completed_without_confirmed_at'::text as issue_code,
        'Thanh toán hoàn thành thiếu confirmed_at'::text as issue,
        'payment'::text as entity_type,
        p.id::text as record_id,
        p.id as payment_id,
        p.customer_id,
        p.kiosk_id,
        coalesce(c.facebook_name, 'Không tên') as customer_name,
        coalesce(k.facebook_name, 'Không tên') as kiosk_name,
        lower(coalesce(p.payment_status, 'unknown')) as status,
        coalesce(p.total_amount, 0) as total_amount,
        coalesce(p.confirmed_at, p.created_at) as event_at
      from public.payments p
      left join public.customers c on c.id = p.customer_id
      left join public.kiosks k on k.id = p.kiosk_id
      where lower(p.payment_status) = 'completed' and p.confirmed_at is null

      union all
      select 'payment_without_customer', 'Thanh toán thiếu khách hàng', 'payment',
        p.id::text, p.id, p.customer_id, p.kiosk_id, 'Không tên',
        coalesce(k.facebook_name, 'Không tên'), lower(coalesce(p.payment_status, 'unknown')),
        coalesce(p.total_amount, 0), coalesce(p.confirmed_at, p.created_at)
      from public.payments p
      left join public.customers c on c.id = p.customer_id
      left join public.kiosks k on k.id = p.kiosk_id
      where p.customer_id is null or c.id is null

      union all
      select 'payment_without_kiosk', 'Thanh toán thiếu Kiosk', 'payment',
        p.id::text, p.id, p.customer_id, p.kiosk_id,
        coalesce(c.facebook_name, 'Không tên'), 'Không tên',
        lower(coalesce(p.payment_status, 'unknown')), coalesce(p.total_amount, 0),
        coalesce(p.confirmed_at, p.created_at)
      from public.payments p
      left join public.customers c on c.id = p.customer_id
      left join public.kiosks k on k.id = p.kiosk_id
      where p.kiosk_id is null or k.id is null

      union all
      select 'kiosk_without_customer', 'Kiosk thiếu khách hàng', 'kiosk',
        k.id::text, null::bigint, k.customer_id, k.id, 'Không tên',
        coalesce(k.facebook_name, 'Không tên'), lower(coalesce(k.status, 'unknown')),
        0::numeric, k.created_at
      from public.kiosks k
      left join public.customers c on c.id = k.customer_id
      where k.customer_id is null or c.id is null

      union all
      select 'kiosk_without_facebook_id', 'Kiosk thiếu Facebook ID', 'kiosk',
        k.id::text, null::bigint, k.customer_id, k.id,
        coalesce(c.facebook_name, 'Không tên'), coalesce(k.facebook_name, 'Không tên'),
        lower(coalesce(k.status, 'unknown')), 0::numeric, k.created_at
      from public.kiosks k
      left join public.customers c on c.id = k.customer_id
      where nullif(trim(k.facebook_id), '') is null

      union all
      select 'duplicate_facebook_id', 'Facebook ID Kiosk bị trùng', 'kiosk',
        k.id::text, null::bigint, k.customer_id, k.id,
        coalesce(c.facebook_name, 'Không tên'), coalesce(k.facebook_name, 'Không tên'),
        lower(coalesce(k.status, 'unknown')), 0::numeric, k.created_at
      from public.kiosks k
      join duplicate_kiosk_ids d on d.facebook_id = trim(k.facebook_id)
      left join public.customers c on c.id = k.customer_id

      union all
      select 'kiosk_without_end_date', 'Kiosk thiếu end_date', 'kiosk',
        k.id::text, null::bigint, k.customer_id, k.id,
        coalesce(c.facebook_name, 'Không tên'), coalesce(k.facebook_name, 'Không tên'),
        lower(coalesce(k.status, 'unknown')), 0::numeric, k.created_at
      from public.kiosks k
      left join public.customers c on c.id = k.customer_id
      where k.end_date is null

      union all
      select 'customer_total_kiosks_mismatch', 'customers.total_kiosks không khớp', 'customer',
        c.id::text, null::bigint, c.id, null::bigint,
        coalesce(c.facebook_name, 'Không tên'), 'Không tên',
        lower(coalesce(c.status, 'unknown')), 0::numeric, c.updated_at
      from public.customers c
      join actual_customer_totals a on a.id = c.id
      where coalesce(c.total_kiosks, 0) <> a.actual_kiosks

      union all
      select 'customer_total_paid_mismatch', 'customers.total_paid không khớp', 'customer',
        c.id::text, null::bigint, c.id, null::bigint,
        coalesce(c.facebook_name, 'Không tên'), 'Không tên',
        lower(coalesce(c.status, 'unknown')), coalesce(c.total_paid, 0), c.updated_at
      from public.customers c
      join actual_customer_totals a on a.id = c.id
      where coalesce(c.total_paid, 0) <> a.actual_paid

      union all
      select 'invalid_completed_payment_amount', 'Thanh toán hoàn thành có số tiền không hợp lệ', 'payment',
        p.id::text, p.id, p.customer_id, p.kiosk_id,
        coalesce(c.facebook_name, 'Không tên'), coalesce(k.facebook_name, 'Không tên'),
        lower(coalesce(p.payment_status, 'unknown')), coalesce(p.total_amount, 0),
        coalesce(p.confirmed_at, p.created_at)
      from public.payments p
      left join public.customers c on c.id = p.customer_id
      left join public.kiosks k on k.id = p.kiosk_id
      where lower(p.payment_status) = 'completed'
        and (
          p.total_amount is null
          or (
            coalesce(to_jsonb(p)->>'transaction_type', 'standard') = 'adjustment'
            and p.total_amount = 0
          )
          or (
            coalesce(to_jsonb(p)->>'transaction_type', 'standard') <> 'adjustment'
            and p.total_amount <= 0
          )
        )

      union all
      select 'duplicated_pending_request', 'Yêu cầu chờ duyệt trùng Facebook ID', 'registration_request',
        r.id::text, null::bigint, r.customer_id, r.kiosk_id,
        coalesce(r.facebook_name, 'Không tên'), coalesce(r.facebook_name, 'Không tên'),
        lower(coalesce(r.status, 'unknown')), coalesce(r.total_amount, 0), r.submitted_at
      from public.registration_requests r
      join duplicate_requests d on d.facebook_id = trim(r.facebook_id)
      where lower(r.status) = 'pending'
    ),
    filtered as (
      select *
      from issues i
      where (p_customer_id is null or i.customer_id = p_customer_id)
        and (p_kiosk_id is null or i.kiosk_id = p_kiosk_id)
        and (
          p_category_id is null
          or exists (
            select 1 from public.kiosks fk
            where fk.id = i.kiosk_id and fk.category_id = p_category_id
          )
        )
        and (
          p_business_type_id is null
          or exists (
            select 1 from public.kiosks fk
            where fk.id = i.kiosk_id and fk.business_type_id = p_business_type_id
          )
        )
        and (p_payment_status is null or i.status = lower(p_payment_status))
        and (
          p_kiosk_status is null
          or exists (
            select 1
            from public.kiosks fk
            where fk.id = i.kiosk_id
              and (
                (lower(p_kiosk_status) = 'expiring_soon'
                  and public.resolve_kiosk_status(fk.status, fk.end_date, warning_days, today_date) = 'warning')
                or public.resolve_kiosk_status(fk.status, fk.end_date, warning_days, today_date) = case when lower(p_kiosk_status) = 'expiring_soon' then 'warning' else lower(p_kiosk_status) end
              )
          )
        )
        and (start_at is null or i.event_at >= start_at)
        and (end_at is null or i.event_at < end_at)
    ),
    counted as (
      select count(*)::bigint as total_rows from filtered
    ),
    issue_groups as (
      select coalesce(jsonb_object_agg(issue_code, issue_count), '{}'::jsonb) as data
      from (
        select issue_code, count(*)::bigint as issue_count
        from filtered
        group by issue_code
      ) grouped
    ),
    paged as (
      select *,
        row_number() over (order by
          case when p_sort_by = 'issue' and sort_direction = 'asc' then issue end asc,
          case when p_sort_by = 'issue' and sort_direction = 'desc' then issue end desc,
          case when coalesce(p_sort_by, 'event_at') = 'event_at' and sort_direction = 'asc' then event_at end asc nulls last,
          event_at desc nulls last,
          record_id desc
        ) as result_order
      from filtered
      order by
        case when p_sort_by = 'issue' and sort_direction = 'asc' then issue end asc,
        case when p_sort_by = 'issue' and sort_direction = 'desc' then issue end desc,
        case when coalesce(p_sort_by, 'event_at') = 'event_at' and sort_direction = 'asc' then event_at end asc nulls last,
        event_at desc nulls last,
        record_id desc
      limit p_page_size offset row_offset
    ),
    rows as (
      select coalesce(jsonb_agg(
        jsonb_build_object(
          'issueCode', issue_code,
          'issue', issue,
          'issueLevel', 'warning',
          'entityType', entity_type,
          'recordId', record_id,
          'paymentId', payment_id,
          'customerId', customer_id,
          'kioskId', kiosk_id,
          'customerName', customer_name,
          'kioskName', kiosk_name,
          'status', status,
          'totalAmount', total_amount,
          'eventAt', event_at
        )
        order by result_order
      ), '[]'::jsonb) as data
      from paged
    )
    select jsonb_build_object(
      'tab', report_type,
      'generatedAt', now(),
      'summary', jsonb_build_object(
        'issueCount', c.total_rows,
        'issuesByType', ig.data
      ),
      'rows', r.data,
      'pagination', jsonb_build_object(
        'page', p_page,
        'pageSize', p_page_size,
        'totalRows', c.total_rows,
        'totalPages', case when c.total_rows = 0 then 0 else ceil(c.total_rows::numeric / p_page_size)::integer end
      )
    )
    into result
    from counted c
    cross join issue_groups ig
    cross join rows r;

  else
    with
    filtered as (
      select
        ca.id as category_id,
        ca.name as category_name,
        bt.id as business_type_id,
        bt.name as business_type_name,
        bt.price_per_month,
        count(distinct k.id)::bigint as kiosk_count,
        count(distinct k.id) filter (where public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) = 'active')::bigint as active_kiosks,
        count(distinct k.id) filter (where public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) = 'pending')::bigint as pending_kiosks,
        count(distinct k.id) filter (where public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) = 'expired')::bigint as expired_kiosks,
        coalesce(sum(p.total_amount), 0) as total_revenue,
        count(distinct p.id)::bigint as completed_payments
      from public.categories ca
      left join public.business_types bt on bt.category_id = ca.id
      left join public.kiosks k
        on k.business_type_id = bt.id
        and (p_customer_id is null or k.customer_id = p_customer_id)
        and (p_kiosk_id is null or k.id = p_kiosk_id)
        and (
          p_kiosk_status is null
          or (lower(p_kiosk_status) = 'expiring_soon'
            and public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) = 'warning')
          or public.resolve_kiosk_status(k.status, k.end_date, warning_days, today_date) = case when lower(p_kiosk_status) = 'expiring_soon' then 'warning' else lower(p_kiosk_status) end
        )
      left join public.payments p
        on p.kiosk_id = k.id
        and lower(p.payment_status) = 'completed'
        and p.confirmed_at is not null
        and (start_at is null or p.confirmed_at >= start_at)
        and (end_at is null or p.confirmed_at < end_at)
        and (p_payment_status is null or lower(p.payment_status) = lower(p_payment_status))
      where (p_category_id is null or ca.id = p_category_id)
        and (p_business_type_id is null or bt.id = p_business_type_id)
      group by ca.id, ca.name, bt.id, bt.name, bt.price_per_month
    ),
    summary as (
      select
        count(distinct category_id)::bigint as total_categories,
        count(business_type_id)::bigint as total_business_types,
        coalesce(sum(kiosk_count), 0) as total_kiosks,
        coalesce(sum(total_revenue), 0) as total_revenue,
        coalesce(sum(completed_payments), 0) as completed_payments
      from filtered
    ),
    counted as (
      select count(*)::bigint as total_rows from filtered
    ),
    paged as (
      select *,
        row_number() over (order by
          case when p_sort_by = 'name' and sort_direction = 'asc' then business_type_name end asc nulls last,
          case when p_sort_by = 'name' and sort_direction = 'desc' then business_type_name end desc nulls last,
          case when p_sort_by = 'kiosks' and sort_direction = 'asc' then kiosk_count end asc,
          case when p_sort_by = 'kiosks' and sort_direction = 'desc' then kiosk_count end desc,
          case when coalesce(p_sort_by, 'revenue') = 'revenue' and sort_direction = 'asc' then total_revenue end asc,
          total_revenue desc,
          business_type_id
        ) as result_order
      from filtered
      order by
        case when p_sort_by = 'name' and sort_direction = 'asc' then business_type_name end asc nulls last,
        case when p_sort_by = 'name' and sort_direction = 'desc' then business_type_name end desc nulls last,
        case when p_sort_by = 'kiosks' and sort_direction = 'asc' then kiosk_count end asc,
        case when p_sort_by = 'kiosks' and sort_direction = 'desc' then kiosk_count end desc,
        case when coalesce(p_sort_by, 'revenue') = 'revenue' and sort_direction = 'asc' then total_revenue end asc,
        total_revenue desc,
        business_type_id
      limit p_page_size offset row_offset
    ),
    rows as (
      select coalesce(jsonb_agg(
        jsonb_build_object(
          'categoryId', category_id,
          'categoryName', coalesce(category_name, 'Chưa phân loại'),
          'businessTypeId', business_type_id,
          'businessTypeName', coalesce(business_type_name, 'Chưa phân loại'),
          'pricePerMonth', coalesce(price_per_month, 0),
          'kioskCount', kiosk_count,
          'activeKiosks', active_kiosks,
          'pendingKiosks', pending_kiosks,
          'expiredKiosks', expired_kiosks,
          'completedPayments', completed_payments,
          'totalRevenue', total_revenue
        )
        order by result_order
      ), '[]'::jsonb) as data
      from paged
    )
    select jsonb_build_object(
      'tab', report_type,
      'generatedAt', now(),
      'summary', jsonb_build_object(
        'totalCategories', coalesce(s.total_categories, 0),
        'totalBusinessTypes', coalesce(s.total_business_types, 0),
        'totalKiosks', coalesce(s.total_kiosks, 0),
        'totalRevenue', coalesce(s.total_revenue, 0),
        'completedCount', coalesce(s.completed_payments, 0)
      ),
      'rows', r.data,
      'pagination', jsonb_build_object(
        'page', p_page,
        'pageSize', p_page_size,
        'totalRows', c.total_rows,
        'totalPages', case when c.total_rows = 0 then 0 else ceil(c.total_rows::numeric / p_page_size)::integer end
      )
    )
    into result
    from summary s
    cross join counted c
    cross join rows r;
  end if;

  result := coalesce(result, jsonb_build_object(
    'tab', report_type,
    'summary', '{}'::jsonb,
    'rows', '[]'::jsonb,
    'pagination', jsonb_build_object(
      'page', p_page, 'pageSize', p_page_size, 'totalRows', 0, 'totalPages', 0
    )
  ));
  return result || jsonb_build_object(
    'warningDays', warning_days,
    'reportDate', today_date
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_status_warning_days()
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select greatest(
    coalesce(
      (
        select case
          when s.value ~ '^\d+$' then s.value::integer
          else null
        end
        from public.settings s
        where s.key = 'warning_days'
      ),
      30
    ),
    0
  )
$function$;

CREATE OR REPLACE FUNCTION public.get_yearly_revenue(year_input integer)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select coalesce(sum(total_amount),0)
  from public.payments
  where payment_status = 'completed'
    and extract(year from confirmed_at at time zone 'Europe/Berlin') = year_input;
$function$;

CREATE OR REPLACE FUNCTION public.handle_payos_webhook(order_code_input bigint, amount_input numeric, payment_link_id_input text DEFAULT NULL::text, reference_input text DEFAULT NULL::text, provider_payload_input jsonb DEFAULT '{}'::jsonb, signature_input text DEFAULT NULL::text, event_key_input text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare order_record public.payos_orders%rowtype; payment_record public.payments%rowtype; event_record public.payos_webhook_events%rowtype; rpc_result jsonb; normalized_event_key text:=coalesce(nullif(btrim(event_key_input),''),'payos:'||order_code_input::text||':'||coalesce(nullif(btrim(reference_input),''),'paid'));
begin
  insert into public.payos_webhook_events(event_key,order_code,signature,payload) values(normalized_event_key,order_code_input,nullif(btrim(signature_input),''),coalesce(provider_payload_input,'{}'::jsonb)) on conflict(event_key) do update set payload=excluded.payload returning * into event_record;
  if event_record.status='processed' then return jsonb_build_object('already_processed',true,'event',to_jsonb(event_record)); end if;
  select * into order_record from public.payos_orders where order_code=order_code_input for update;
  if not found then raise exception 'Không tìm thấy PayOS order.' using errcode='P0002'; end if;
  if order_record.amount<>amount_input then raise exception 'Số tiền webhook không khớp PayOS order.' using errcode='22023'; end if;
  if order_record.status='paid' then update public.payos_webhook_events set status='processed',processed_at=pg_catalog.now() where id=event_record.id returning * into event_record; return jsonb_build_object('already_processed',true,'order',to_jsonb(order_record),'event',to_jsonb(event_record)); end if;
  if order_record.purpose='crm_payment' then
    select * into payment_record from public.payments where id=order_record.payment_id for update;
    if not found or payment_record.total_amount<>amount_input then raise exception 'Số tiền webhook không khớp thanh toán.' using errcode='22023'; end if;
    if payment_record.payment_status='completed' then update public.payos_orders set status='paid',active_slot=null,confirmed_at=coalesce(confirmed_at,pg_catalog.now()),processed_at=coalesce(processed_at,pg_catalog.now()),provider_payload=provider_payload||coalesce(provider_payload_input,'{}'::jsonb),updated_at=pg_catalog.now() where id=order_record.id returning * into order_record; update public.payos_webhook_events set status='processed',processed_at=pg_catalog.now(),error='Payment already completed; paid sibling requires reconciliation.' where id=event_record.id returning * into event_record; return jsonb_build_object('already_processed',true,'reconciliation_required',true,'order',to_jsonb(order_record),'event',to_jsonb(event_record)); end if;
    if payment_record.payment_status<>'pending' then raise exception 'Thanh toán không còn Pending.' using errcode='22023'; end if;
    if payment_record.registration_batch_id is not null then rpc_result:=private.confirm_registration_batch_from_payos(payment_record.id,'PayOS paid: '||coalesce(nullif(btrim(reference_input),''),order_record.order_code::text)); else rpc_result:=private.confirm_crm_payment_from_payos(payment_record.id,'PayOS paid: '||coalesce(nullif(btrim(reference_input),''),order_record.order_code::text)); update public.registration_requests set status='approved',reviewed_at=coalesce(reviewed_at,pg_catalog.now()) where payment_id=payment_record.id and status='pending'; end if;
    update public.payos_orders set status='cancelled',active_slot=null,processed_at=coalesce(processed_at,pg_catalog.now()),updated_at=pg_catalog.now() where payment_id=payment_record.id and id<>order_record.id and status='pending';
  elsif order_record.purpose='wallet_topup' then rpc_result:=private.post_wallet_ledger(order_record.wallet_user_id,order_record.amount,'admin_adjustment','payos_orders',order_record.id::text,'payos-paid:'||order_record.order_code::text,'Nạp xu PayOS','PayOS paid: '||coalesce(nullif(btrim(reference_input),''),order_record.order_code::text),jsonb_build_object('source','payos','order_code',order_record.order_code),null,'system');
  else raise exception 'Mục đích PayOS không hợp lệ.' using errcode='22023'; end if;
  update public.payos_orders set status='paid',active_slot=null,payment_link_id=coalesce(nullif(btrim(payment_link_id_input),''),payment_link_id),provider_payload=provider_payload||coalesce(provider_payload_input,'{}'::jsonb),confirmed_at=coalesce(confirmed_at,pg_catalog.now()),processed_at=pg_catalog.now(),updated_at=pg_catalog.now() where id=order_record.id returning * into order_record;
  update public.payos_webhook_events set status='processed',processed_at=pg_catalog.now() where id=event_record.id returning * into event_record;
  return jsonb_build_object('order',to_jsonb(order_record),'event',to_jsonb(event_record),'result',rpc_result,'already_processed',false);
end;$function$;

CREATE OR REPLACE FUNCTION public.is_system_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select exists (
    select 1
    from public.user_profiles up
    where up.user_id = (select auth.uid())
      and up.status = 'active'
      and up.web_access_enabled
      and up.is_system_admin
  );
$function$;

CREATE OR REPLACE FUNCTION public.log_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  changer_text text := coalesce(auth.uid()::text, 'Hệ thống');
begin
  if (TG_OP = 'INSERT') then
    insert into public.logs (
      action,
      table_name,
      record_id,
      new_value,
      new_data,
      created_by,
      created_at
    )
    values (
      'INSERT',
      TG_TABLE_NAME,
      NEW.id,
      to_jsonb(NEW),
      to_jsonb(NEW),
      changer_text,
      now()
    );

    return NEW;

  elsif (TG_OP = 'UPDATE') then
    insert into public.logs (
      action,
      table_name,
      record_id,
      old_value,
      new_value,
      old_data,
      new_data,
      created_by,
      created_at
    )
    values (
      'UPDATE',
      TG_TABLE_NAME,
      NEW.id,
      to_jsonb(OLD),
      to_jsonb(NEW),
      to_jsonb(OLD),
      to_jsonb(NEW),
      changer_text,
      now()
    );

    return NEW;

  elsif (TG_OP = 'DELETE') then
    insert into public.logs (
      action,
      table_name,
      record_id,
      old_value,
      old_data,
      created_by,
      created_at
    )
    values (
      'DELETE',
      TG_TABLE_NAME,
      OLD.id,
      to_jsonb(OLD),
      to_jsonb(OLD),
      changer_text,
      now()
    );

    return OLD;
  end if;

  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.prepare_public_kiosk_renewal(kiosk_id_input bigint, months_input integer, nonce_hash_input text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare kiosk_record public.kiosks%rowtype; package_record public.business_types%rowtype; payment_record public.payments%rowtype;
declare intent_key text := 'public-renewal:' || kiosk_id_input::text || ':' || months_input::text;
begin
  if coalesce(auth.jwt() ->> 'role', '') <> 'service_role' then raise exception 'Chỉ API server được chuẩn bị gia hạn công khai.' using errcode='42501'; end if;
  if months_input not in (1,3,6,12) then raise exception 'Thời hạn gia hạn không được hỗ trợ.' using errcode='22023'; end if;
  update private.public_renewal_authorizations set consumed_at=now()
  where nonce_hash=nonce_hash_input and kiosk_id=kiosk_id_input and consumed_at is null and expires_at>now();
  if not found then raise exception 'Quyền gia hạn đã hết hạn hoặc đã được sử dụng.' using errcode='42501'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(intent_key, 0));
  select * into kiosk_record from public.kiosks where id=kiosk_id_input for update;
  if not found or kiosk_record.customer_id is null then raise exception 'Không tìm thấy Kiosk hợp lệ.' using errcode='P0002'; end if;
  select * into package_record from public.business_types where id=kiosk_record.business_type_id and is_active=true;
  if not found or package_record.price_per_month is null or package_record.price_per_month<=0 then raise exception 'Giá dịch vụ hiện tại không hợp lệ.' using errcode='22023'; end if;
  select * into payment_record from public.payments
  where payment_intent_key=intent_key and payment_status='pending' order by id desc limit 1 for update;
  if found then
    if payment_record.total_amount <> package_record.price_per_month*months_input then
      raise exception 'Giá của ý định gia hạn hiện tại không còn hợp lệ; vui lòng liên hệ Admin.' using errcode='22023';
    end if;
  else
    insert into public.payments(customer_id,kiosk_id,months,price_per_month,discount,total_amount,payment_method,payment_status,note,transaction_type,service_month_delta,payment_intent_key)
    values(kiosk_record.customer_id,kiosk_record.id,months_input,package_record.price_per_month,0,package_record.price_per_month*months_input,'transfer','pending','Public PayOS Kiosk renewal','standard',0,intent_key)
    returning * into payment_record;
  end if;
  return jsonb_build_object('payment',to_jsonb(payment_record),'kiosk_name',kiosk_record.facebook_name,'business_type',package_record.name);
end;$function$;

CREATE OR REPLACE FUNCTION public.prepare_registration_checkout_v3(request_ids_input bigint[], phone_input text, promotion_code_input text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if coalesce(auth.jwt()->>'role', '') <> 'service_role' then
    raise exception 'Chỉ API server được chuẩn bị thanh toán đăng ký.' using errcode = '42501';
  end if;
  return private.materialize_registration_checkout_v3(
    request_ids_input,
    phone_input,
    promotion_code_input
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_public_renewal_payos_order(payment_id_input bigint, order_code_input bigint, amount_input numeric, description_input text, checkout_url_input text DEFAULT NULL::text, qr_code_input text DEFAULT NULL::text, payment_link_id_input text DEFAULT NULL::text, provider_payload_input jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare order_record public.payos_orders%rowtype;
begin
  if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'Chỉ API server được ghi PayOS order.' using errcode='42501'; end if;
  if not exists(select 1 from public.payments where id=payment_id_input and note='Public PayOS Kiosk renewal') then raise exception 'Thanh toán gia hạn không hợp lệ.' using errcode='22023'; end if;
  order_record := private.reserve_crm_payos_order(payment_id_input,order_code_input,amount_input,description_input,checkout_url_input,qr_code_input,payment_link_id_input,provider_payload_input);
  return to_jsonb(order_record);
end;$function$;

CREATE OR REPLACE FUNCTION public.record_registration_payos_order(payment_id_input bigint, order_code_input bigint, amount_input numeric, description_input text, checkout_url_input text DEFAULT NULL::text, qr_code_input text DEFAULT NULL::text, payment_link_id_input text DEFAULT NULL::text, provider_payload_input jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare order_record public.payos_orders%rowtype;
begin
  if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'Chỉ API server được ghi PayOS order đăng ký.' using errcode='42501'; end if;
  if not exists(select 1 from public.payments p join public.registration_batches b on b.payment_id=p.id where p.id=payment_id_input and p.registration_batch_id=b.id and p.payment_status='pending' and b.status='pending' and p.total_amount=b.total_amount and p.total_amount=amount_input) then raise exception 'Thanh toán lô đăng ký không hợp lệ.' using errcode='22023'; end if;
  order_record:=private.reserve_crm_payos_order(payment_id_input,order_code_input,amount_input,description_input,checkout_url_input,qr_code_input,payment_link_id_input,provider_payload_input);
  return to_jsonb(order_record);
end;$function$;

CREATE OR REPLACE FUNCTION public.register_public_renewal_authorization(kiosk_id_input bigint, nonce_hash_input text, expires_at_input timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if coalesce(auth.jwt() ->> 'role', '') <> 'service_role' then
    raise exception 'Chỉ API server được cấp quyền gia hạn.' using errcode = '42501';
  end if;

  if expires_at_input <= now()
    or expires_at_input > now() + interval '15 minutes' then
    raise exception 'Hạn token không hợp lệ.' using errcode = '22023';
  end if;

  insert into private.public_renewal_authorizations(
    nonce_hash,
    kiosk_id,
    expires_at
  ) values (
    nonce_hash_input,
    kiosk_id_input,
    expires_at_input
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_customer_status(stored_status text, kiosk_statuses text[])
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case
    when lower(coalesce(stored_status, 'inactive')) <> 'active'
      then lower(coalesce(stored_status, 'inactive'))
    when coalesce(cardinality(kiosk_statuses), 0) = 0 then 'active'
    when 'warning' = any(kiosk_statuses) then 'warning'
    when 'active' = any(kiosk_statuses) then 'active'
    when 'pending' = any(kiosk_statuses) then 'pending'
    when 'suspended' = any(kiosk_statuses) then 'suspended'
    when 'expired' = any(kiosk_statuses) then 'expired'
    else 'inactive'
  end
$function$;

CREATE OR REPLACE FUNCTION public.resolve_kiosk_status(stored_status text, end_date_value date, warning_days_value integer, today_value date)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case
    when lower(coalesce(stored_status, 'inactive')) not in ('active', 'warning', 'expired')
      then lower(coalesce(stored_status, 'inactive'))
    when end_date_value is null then lower(coalesce(stored_status, 'inactive'))
    when end_date_value < today_value then 'expired'
    when end_date_value <= today_value + greatest(coalesce(warning_days_value, 30), 0) then 'warning'
    else 'active'
  end
$function$;

CREATE OR REPLACE FUNCTION public.submit_public_registration(customer_input jsonb, kiosks_input jsonb, bill_input jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  kiosk_item jsonb; bt public.business_types%rowtype; request_id_value bigint;
  used_request_ids bigint[] := array[]::bigint[]; result_items jsonb := '[]'::jsonb;
  item_number integer := 0; months_value integer; discount_value numeric;
  start_on date; end_on date; total_value numeric;
  customer_name text := nullif(trim(customer_input->>'facebook_name'), '');
  customer_phone text := nullif(trim(customer_input->>'phone'), '');
begin
  if customer_input is null or jsonb_typeof(customer_input) <> 'object'
    or customer_name is null or customer_phone is null then
    raise exception 'Tên Facebook và số điện thoại là bắt buộc.' using errcode = '22023';
  end if;
  if kiosks_input is null or jsonb_typeof(kiosks_input) <> 'array'
    or jsonb_array_length(kiosks_input) < 1 or jsonb_array_length(kiosks_input) > 20 then
    raise exception 'Cần đăng ký từ 1 đến 20 kiosk.' using errcode = '22023';
  end if;
  for kiosk_item in select value from jsonb_array_elements(kiosks_input) loop
    item_number := item_number + 1;
    if nullif(trim(kiosk_item->>'facebook_name'), '') is null
      or nullif(trim(kiosk_item->>'facebook_link'), '') is null then
      raise exception 'Kiosk số % cần tên Facebook và link Facebook.', item_number using errcode = '22023';
    end if;
    if nullif(trim(kiosk_item->>'facebook_id'), '') is not null
      and trim(kiosk_item->>'facebook_id') !~ '^[0-9]+$' then
      raise exception 'Facebook ID của kiosk số % chỉ được chứa chữ số.', item_number using errcode = '22023';
    end if;
    if nullif(pg_catalog.regexp_replace(coalesce(kiosk_item->>'facebook_id', ''), '[^0-9]', '', 'g'), '') is null
      or trim(kiosk_item->>'facebook_id') !~ '^[0-9]{5,30}$' then
      raise exception 'Kiosk số % cần Facebook ID dạng số hợp lệ.', item_number using errcode = '22023';
    end if;
    begin
      months_value := (kiosk_item->>'months')::integer;
      discount_value := coalesce((kiosk_item->>'discount')::numeric, 0);
      select * into bt from public.business_types
      where id = (kiosk_item->>'business_type_id')::bigint and is_active = true;
    exception when invalid_text_representation then
      raise exception 'Thông tin dịch vụ của kiosk số % không hợp lệ.', item_number using errcode = '22023';
    end;
    if not found then raise exception 'Dịch vụ của kiosk số % không hoạt động.', item_number using errcode = '22023'; end if;
    request_id_value := null;
    select r.id into request_id_value from public.registration_requests r
    where r.status = 'awaiting_payment' and r.id <> all(used_request_ids)
      and pg_catalog.regexp_replace(coalesce(r.phone, ''), '[^0-9+]', '', 'g')
        = pg_catalog.regexp_replace(customer_phone, '[^0-9+]', '', 'g')
      and r.facebook_id = trim(kiosk_item->>'facebook_id')
      and r.business_type_id = bt.id and r.months = months_value
      and r.total_amount = (bt.price_per_month * months_value) - discount_value
      and (r.payment_id is null or exists (select 1 from public.payments p
        where p.id = r.payment_id and p.payment_status = 'pending'))
    order by r.id desc limit 1 for update;
    if not found then
      request_id_value := public.submit_registration_request(
        kiosk_item->>'facebook_name', customer_phone, trim(kiosk_item->>'facebook_id'),
        kiosk_item->>'facebook_link', customer_input->>'address',
        coalesce(kiosk_item->>'note', customer_input->>'note'), bt.category_id, bt.id,
        months_value, discount_value, kiosk_item->>'discount_reason');
    end if;
    used_request_ids := array_append(used_request_ids, request_id_value);
    update public.registration_requests set status = 'awaiting_payment',
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('workflow', 'public_payos')
    where id = request_id_value;
    start_on := (pg_catalog.now() at time zone 'Europe/Berlin')::date;
    end_on := (start_on + pg_catalog.make_interval(months => months_value))::date;
    total_value := (bt.price_per_month * months_value) - discount_value;
    result_items := result_items || jsonb_build_array(jsonb_build_object(
      'request', jsonb_build_object('id', request_id_value, 'status', 'awaiting_payment'),
      'preview', jsonb_build_object('startDate', start_on, 'endDate', end_on, 'months', months_value,
        'pricePerMonth', bt.price_per_month, 'discount', discount_value, 'totalAmount', total_value),
      'businessType', jsonb_build_object('id', bt.id, 'name', bt.name)));
  end loop;
  return jsonb_build_object('customer', jsonb_build_object('facebook_name', customer_name,
    'facebook_link', nullif(trim(customer_input->>'facebook_link'), ''), 'phone', customer_phone),
    'kiosks', result_items, 'status', 'awaiting_payment',
    'bill_received', bill_input is not null and bill_input <> 'null'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION public.submit_registration_request(facebook_name_input text, phone_input text, facebook_id_input text, facebook_link_input text, address_input text, note_input text, category_id_input bigint, business_type_id_input bigint, months_input integer, discount_input numeric, discount_reason_input text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  bt public.business_types%rowtype;
  request_id bigint;
  start_on date;
  end_on date;
  subtotal numeric;
  final_total numeric;
begin
  if length(trim(coalesce(facebook_name_input, ''))) < 1 then raise exception 'Tên Facebook là bắt buộc.'; end if;
  if length(trim(coalesce(phone_input, ''))) < 6 then raise exception 'Số điện thoại không hợp lệ.'; end if;
  if months_input is null or months_input < 1 or months_input > 60 then raise exception 'Số tháng phải từ 1 đến 60.'; end if;
  if coalesce(discount_input, 0) < 0 then raise exception 'Giảm giá không hợp lệ.'; end if;
  select * into bt from public.business_types where id = business_type_id_input and is_active = true;
  if not found then raise exception 'Loại hình kinh doanh không hoạt động.'; end if;
  if bt.category_id is distinct from category_id_input then raise exception 'Danh mục và loại hình kinh doanh không khớp.'; end if;
  subtotal := bt.price_per_month * months_input;
  final_total := subtotal - coalesce(discount_input, 0);
  if final_total < 0 then raise exception 'Giảm giá không được lớn hơn tạm tính.'; end if;
  if coalesce(discount_input, 0) > 0 and length(trim(coalesce(discount_reason_input, ''))) < 1 then
    raise exception 'Cần nhập lý do giảm giá.';
  end if;
  start_on := (pg_catalog.now() at time zone 'Europe/Berlin')::date;
  end_on := (start_on + pg_catalog.make_interval(months => months_input))::date;
  insert into public.registration_requests(facebook_name, facebook_id, facebook_link, phone, address, note,
    service_name, category_id, business_type_id, requested_start_date, requested_end_date,
    months, price_per_month, discount, discount_reason, total_amount, payment_method, status)
  values(trim(facebook_name_input), nullif(trim(coalesce(facebook_id_input, '')), ''),
    nullif(trim(coalesce(facebook_link_input, '')), ''), trim(phone_input),
    nullif(trim(coalesce(address_input, '')), ''), nullif(trim(coalesce(note_input, '')), ''),
    bt.name, bt.category_id, bt.id, start_on, end_on, months_input, bt.price_per_month,
    coalesce(discount_input, 0), nullif(trim(coalesce(discount_reason_input, '')), ''),
    final_total, 'transfer', 'awaiting_payment') returning id into request_id;
  return request_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_customer_kiosk_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  -- Xử lý khi THÊM một kiosk mới
  IF (TG_OP = 'INSERT') THEN
    IF NEW.customer_id IS NOT NULL THEN
      UPDATE public.customers
      SET total_kiosks = COALESCE(total_kiosks, 0) + 1
      WHERE id = NEW.customer_id;
    END IF;
  -- Xử lý khi XÓA một kiosk
  ELSIF (TG_OP = 'DELETE') THEN
    IF OLD.customer_id IS NOT NULL THEN
      UPDATE public.customers
      SET total_kiosks = GREATEST(COALESCE(total_kiosks, 1) - 1, 0)
      WHERE id = OLD.customer_id;
    END IF;
  -- Xử lý khi CẬP NHẬT một kiosk (ví dụ: đổi kiosk từ khách hàng A sang B)
  ELSIF (TG_OP = 'UPDATE') THEN
    IF OLD.customer_id IS DISTINCT FROM NEW.customer_id THEN
      -- Giảm số đếm cho khách hàng cũ (nếu có)
      IF OLD.customer_id IS NOT NULL THEN
        UPDATE public.customers
        SET total_kiosks = GREATEST(COALESCE(total_kiosks, 1) - 1, 0)
        WHERE id = OLD.customer_id;
      END IF;
      -- Tăng số đếm cho khách hàng mới (nếu có)
      IF NEW.customer_id IS NOT NULL THEN
        UPDATE public.customers
        SET total_kiosks = COALESCE(total_kiosks, 0) + 1
        WHERE id = NEW.customer_id;
      END IF;
    END IF;
  END IF;

  IF (TG_OP = 'DELETE') THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.write_audit_log(module_input text, action_input text, entity_input text DEFAULT NULL::text, record_id_input text DEFAULT NULL::text, before_input jsonb DEFAULT NULL::jsonb, after_input jsonb DEFAULT NULL::jsonb, reason_input text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor public.user_roles%rowtype;
  audit_record public.audit_logs%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Bạn phải đăng nhập để ghi audit log.'
      using errcode = '42501';
  end if;

  select *
  into actor
  from public.user_roles ur
  where ur.user_id = auth.uid()
    and ur.is_active = true;
  if not found then
    raise exception 'Tài khoản không hoạt động.'
      using errcode = '42501';
  end if;

  insert into public.audit_logs(
    actor_id,
    actor_name,
    actor_type,
    actor_role,
    module,
    entity,
    record_id,
    action,
    before,
    after,
    reason
  )
  values(
    actor.user_id,
    coalesce(actor.display_name, actor.username),
    'staff',
    actor.role,
    module_input,
    entity_input,
    record_id_input,
    action_input,
    before_input,
    after_input,
    reason_input
  )
  returning * into audit_record;

  return to_jsonb(audit_record);
end;
$function$;

CREATE OR REPLACE FUNCTION private.assert_audit_access()
 RETURNS user_roles
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor public.user_roles%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Bạn phải đăng nhập để xem audit log.'
      using errcode = '42501';
  end if;

  select *
  into actor
  from public.user_roles ur
  where ur.user_id = auth.uid()
    and ur.is_active = true
    and (
      lower(ur.role) = 'admin'
      or exists (
        select 1
        from public.role_permissions rp
        where lower(rp.role) = lower(ur.role)
          and 'logs' = any(rp.permissions)
      )
    );

  if not found then
    raise exception 'Không có quyền xem audit log.'
      using errcode = '42501';
  end if;
  return actor;
end;
$function$;

