  raise exception 'Nhân viên không được xóa cứng. Hãy vô hiệu hóa tài khoản.'
    using errcode = '23514';
end;
$function$;

CREATE OR REPLACE FUNCTION private.protect_completed_batch_promotion_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if exists(select 1 from public.payments p where p.registration_batch_id=old.id and p.payment_status='completed') then
    raise exception 'Không thể thay đổi ảnh chụp ưu đãi của thanh toán đã hoàn tất.' using errcode='23514';
  end if;
  return new;
end;$function$;

CREATE OR REPLACE FUNCTION private.protect_payment_records()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  workflow_action text := coalesce(
    pg_catalog.current_setting('app.payment_workflow_action', true),
    ''
  );
begin
  if tg_op = 'DELETE' then
    raise exception 'Thanh toán không bao giờ được xóa cứng.' using errcode = '23514';
  end if;

  if tg_op = 'INSERT' then
    if pg_catalog.lower(coalesce(new.payment_status, '')) <> 'pending'
      and workflow_action <> 'adjustment' then
      raise exception 'Thanh toán mới phải bắt đầu ở trạng thái Pending.' using errcode = '23514';
    end if;
    return new;
  end if;

  if pg_catalog.lower(old.payment_status) = 'completed' then
    if workflow_action = 'historical_correction' then
      -- Future columns are protected by default. Only these four explicitly
      -- audited historical fields may differ inside the dedicated RPC.
      if (
        pg_catalog.to_jsonb(new)
          - array['start_date', 'end_date', 'months', 'total_amount']::text[]
      ) is distinct from (
        pg_catalog.to_jsonb(old)
          - array['start_date', 'end_date', 'months', 'total_amount']::text[]
      ) then
        raise exception 'Sửa dữ liệu lịch sử chỉ được đổi ngày, số tháng và số tiền.'
          using errcode = '42501';
      end if;
      return new;
    end if;

    if new.id is distinct from old.id
      or new.created_at is distinct from old.created_at
      or new.customer_id is distinct from old.customer_id
      or new.kiosk_id is distinct from old.kiosk_id
      or new.start_date is distinct from old.start_date
      or new.end_date is distinct from old.end_date
      or new.months is distinct from old.months
      or new.price_per_month is distinct from old.price_per_month
      or new.discount is distinct from old.discount
      or new.discount_reason is distinct from old.discount_reason
      or new.total_amount is distinct from old.total_amount
      or new.payment_method is distinct from old.payment_method
      or new.payment_status is distinct from old.payment_status
      or new.confirmed_at is distinct from old.confirmed_at
      or new.confirmed_by is distinct from old.confirmed_by
      or new.transaction_type is distinct from old.transaction_type
      or new.adjusts_payment_id is distinct from old.adjusts_payment_id
      or new.adjustment_reason is distinct from old.adjustment_reason
      or new.service_month_delta is distinct from old.service_month_delta then
      raise exception 'Không được sửa trường tài chính của thanh toán Completed. Hãy tạo giao dịch điều chỉnh.'
        using errcode = '23514';
    end if;
    return new;
  end if;

  if pg_catalog.lower(old.payment_status) in ('rejected', 'cancelled') then
    if new is distinct from old then
      raise exception 'Thanh toán Rejected/Cancelled là trạng thái kết thúc.' using errcode = '23514';
    end if;
    return new;
  end if;

  if pg_catalog.lower(old.payment_status) <> 'pending' then
    raise exception 'Trạng thái thanh toán hiện tại không hợp lệ.' using errcode = '23514';
  end if;
  if pg_catalog.lower(new.payment_status) = 'completed' and workflow_action <> 'confirm' then
    raise exception 'Chỉ confirm_payment() được hoàn thành thanh toán.' using errcode = '23514';
  end if;
  if pg_catalog.lower(new.payment_status) = 'rejected' and workflow_action <> 'reject' then
    raise exception 'Chỉ reject_payment() được từ chối thanh toán.' using errcode = '23514';
  end if;
  if pg_catalog.lower(new.payment_status) = 'cancelled' and workflow_action <> 'cancel' then
    raise exception 'Chỉ cancel_payment() được hủy thanh toán.' using errcode = '23514';
  end if;
  if pg_catalog.lower(new.payment_status) not in ('pending', 'completed', 'rejected', 'cancelled') then
    raise exception 'Trạng thái thanh toán không hợp lệ.' using errcode = '23514';
  end if;
  if pg_catalog.lower(new.payment_status) = 'pending'
    and workflow_action <> 'edit'
    and (
      new.customer_id is distinct from old.customer_id
      or new.kiosk_id is distinct from old.kiosk_id
      or new.start_date is distinct from old.start_date
      or new.end_date is distinct from old.end_date
      or new.months is distinct from old.months
      or new.price_per_month is distinct from old.price_per_month
      or new.discount is distinct from old.discount
      or new.discount_reason is distinct from old.discount_reason
      or new.total_amount is distinct from old.total_amount
      or new.payment_method is distinct from old.payment_method
    ) then
    raise exception 'Trường tài chính của thanh toán Pending phải được sửa qua update_pending_payment().'
      using errcode = '23514';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.protect_payos_checkout_metadata()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  metadata_changed boolean;
begin
  if tg_op = 'INSERT' then
    metadata_changed :=
      new.payos_order_code is not null
      or new.payos_payment_link_id is not null
      or new.payos_checkout_url is not null
      or new.payos_expire_at is not null
      or new.payos_amount_snapshot is not null
      or new.payos_checkout_state is not null
      or new.payos_claim_token is not null
      or new.payos_claim_expires_at is not null
      or new.payos_attempt <> 0;

    if metadata_changed
      and coalesce(current_setting('app.payos_metadata_write', true), '') <> 'allowed' then
      raise exception 'Metadata payOS chỉ được tạo qua RPC phía server.'
        using errcode = '42501';
    end if;
    return new;
  end if;

  metadata_changed :=
    new.payos_order_code is distinct from old.payos_order_code
    or new.payos_payment_link_id is distinct from old.payos_payment_link_id
    or new.payos_checkout_url is distinct from old.payos_checkout_url
    or new.payos_expire_at is distinct from old.payos_expire_at
    or new.payos_amount_snapshot is distinct from old.payos_amount_snapshot
    or new.payos_checkout_state is distinct from old.payos_checkout_state
    or new.payos_claim_token is distinct from old.payos_claim_token
    or new.payos_claim_expires_at is distinct from old.payos_claim_expires_at
    or new.payos_attempt is distinct from old.payos_attempt;

  if metadata_changed
    and coalesce(current_setting('app.payos_metadata_write', true), '') <> 'allowed' then
    raise exception 'Metadata payOS chỉ được cập nhật qua RPC phía server.'
      using errcode = '42501';
  end if;

  if lower(coalesce(old.payment_status, '')) = 'completed'
    and metadata_changed then
    raise exception 'Metadata của thanh toán Completed là bất biến.'
      using errcode = '23514';
  end if;

  if old.payos_checkout_state in ('reserved', 'creating', 'ready')
    and new.total_amount is distinct from old.total_amount then
    raise exception 'Không thể đổi số tiền khi checkout payOS đang hoạt động.'
      using errcode = '23514';
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.recalculate_customer_payment_total(customer_id_input bigint)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  update public.customers c
  set
    total_paid = coalesce((
      select sum(p.total_amount)
      from public.payments p
      where p.customer_id = customer_id_input
        and lower(coalesce(p.payment_status, '')) = 'completed'
        and p.confirmed_at is not null
    ), 0),
    last_payment_date = (
      select max((p.confirmed_at at time zone 'Asia/Ho_Chi_Minh')::date)
      from public.payments p
      where p.customer_id = customer_id_input
        and lower(coalesce(p.payment_status, '')) = 'completed'
        and p.confirmed_at is not null
    ),
    updated_at = pg_catalog.now()
  where c.id = customer_id_input;
$function$;

CREATE OR REPLACE FUNCTION private.recalculate_kiosk_payment_total(kiosk_id_input bigint)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with kiosk_ledger as (
    select
      p.total_amount as amount,
      (p.confirmed_at at time zone 'Asia/Ho_Chi_Minh')::date as paid_on
    from public.payments p
    where p.registration_batch_id is null
      and p.kiosk_id = kiosk_id_input
      and pg_catalog.lower(coalesce(p.payment_status, '')) = 'completed'
      and p.confirmed_at is not null

    union all

    select
      i.total_amount as amount,
      (p.confirmed_at at time zone 'Asia/Ho_Chi_Minh')::date as paid_on
    from public.registration_batch_items i
    join public.registration_batches b on b.id = i.batch_id
    join public.payments p on p.id = b.payment_id
    where i.kiosk_id = kiosk_id_input
      and p.registration_batch_id = b.id
      and pg_catalog.lower(coalesce(p.payment_status, '')) = 'completed'
      and p.confirmed_at is not null
  ), totals as (
    select coalesce(sum(amount), 0) as amount, max(paid_on) as paid_on
    from kiosk_ledger
  )
  update public.kiosks k
  set
    total_paid = totals.amount,
    kiosk_total_paid = totals.amount,
    last_payment_date = totals.paid_on
  from totals
  where k.id = kiosk_id_input;
$function$;

CREATE OR REPLACE FUNCTION private.reserve_crm_payos_order(payment_id_input bigint, order_code_input bigint, amount_input numeric, description_input text, checkout_url_input text, qr_code_input text, payment_link_id_input text, provider_payload_input jsonb)
 RETURNS payos_orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare payment_record public.payments%rowtype; order_record public.payos_orders%rowtype; old_order public.payos_orders%rowtype;
declare expiry timestamptz;
begin
  select * into payment_record from public.payments where id=payment_id_input for update;
  if not found or payment_record.payment_status<>'pending' or payment_record.total_amount<>amount_input then raise exception 'Thanh toán Pending không hợp lệ.' using errcode='22023'; end if;
  begin expiry := to_timestamp((provider_payload_input->>'expiresAt')::bigint); exception when others then expiry := null; end;
  select * into old_order from public.payos_orders where payment_id=payment_id_input and purpose='crm_payment' and status='pending' and active_slot is true order by id desc limit 1 for update;
  if found and old_order.order_code<>order_code_input then
    if old_order.expires_at is null or old_order.expires_at>now() then raise exception 'Thanh toán đã có một mã PayOS còn hiệu lực.' using errcode='23505'; end if;
    update public.payos_orders set status='expired',active_slot=null,processed_at=coalesce(processed_at,now()),updated_at=now() where id=old_order.id;
  end if;
  insert into public.payos_orders(order_code,purpose,payment_id,amount,description,checkout_url,qr_code,payment_link_id,provider_payload,created_by,expires_at,active_slot)
  values(order_code_input,'crm_payment',payment_id_input,amount_input,nullif(trim(description_input),''),nullif(trim(checkout_url_input),''),nullif(trim(qr_code_input),''),nullif(trim(payment_link_id_input),''),coalesce(provider_payload_input,'{}'::jsonb),auth.uid(),expiry,true)
  on conflict(order_code) do update set checkout_url=excluded.checkout_url,qr_code=excluded.qr_code,payment_link_id=excluded.payment_link_id,
    provider_payload=excluded.provider_payload,expires_at=coalesce(excluded.expires_at,public.payos_orders.expires_at),updated_at=now()
  where public.payos_orders.status='pending' returning * into order_record;
  if old_order.id is not null and old_order.id<>order_record.id then update public.payos_orders set superseded_by_order_id=order_record.id where id=old_order.id; end if;
  return order_record;
end;$function$;

CREATE OR REPLACE FUNCTION private.sync_completed_payment_totals()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  affected_kiosk_id bigint;
begin
  if tg_op in ('UPDATE', 'DELETE') then
    if old.customer_id is not null then
      perform private.recalculate_customer_payment_total(old.customer_id);
    end if;
    if old.registration_batch_id is not null then
      for affected_kiosk_id in
        select distinct i.kiosk_id
        from public.registration_batch_items i
        where i.batch_id = old.registration_batch_id
      loop
        perform private.recalculate_kiosk_payment_total(affected_kiosk_id);
      end loop;
    elsif old.kiosk_id is not null then
      perform private.recalculate_kiosk_payment_total(old.kiosk_id);
    end if;
  end if;

  if tg_op in ('INSERT', 'UPDATE') then
    if new.customer_id is not null then
      perform private.recalculate_customer_payment_total(new.customer_id);
    end if;
    if new.registration_batch_id is not null then
      for affected_kiosk_id in
        select distinct i.kiosk_id
        from public.registration_batch_items i
        where i.batch_id = new.registration_batch_id
      loop
        perform private.recalculate_kiosk_payment_total(affected_kiosk_id);
      end loop;
    elsif new.kiosk_id is not null then
      perform private.recalculate_kiosk_payment_total(new.kiosk_id);
    end if;
    return new;
  end if;

  return old;
end;
$function$;

CREATE OR REPLACE FUNCTION private.sync_completed_renewal_kiosk_period()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if coalesce(
    pg_catalog.current_setting('app.payment_workflow_action', true),
    ''
  ) = 'historical_correction' then
    return null;
  end if;

  if new.registration_batch_id is null
    and new.payment_status = 'completed'
    and new.start_date is not null
    and new.end_date is not null then
    update public.kiosks
    set status = 'active', end_date = new.end_date
    where id = new.kiosk_id;
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION private.sync_registration_payment_intent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.payment_id is not null and (tg_op = 'INSERT' or old.payment_id is distinct from new.payment_id) then
    update public.payments
    set registration_request_id = new.id,
        payment_intent_key = 'registration:' || new.id::text
    where id = new.payment_id
      and (registration_request_id is null or registration_request_id = new.id);
  end if;
  return new;
end;$function$;

CREATE OR REPLACE FUNCTION private.sync_registration_period_from_completed_payment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.registration_batch_id is null
    and old.payment_status = 'pending'
    and new.payment_status = 'completed'
    and new.start_date is not null
    and new.end_date is not null then
    update public.registration_requests
    set requested_start_date = new.start_date,
        requested_end_date = new.end_date
    where payment_id = new.id;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION private.write_payment_audit(action_input text, before_input jsonb, after_input jsonb, reason_input text, actor_input user_roles)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  insert into public.audit_logs(
    actor_id,
    actor_name,
    actor_role,
    module,
    action,
    before,
    after,
    reason
  )
  values(
    (actor_input).user_id,
    coalesce((actor_input).display_name, (actor_input).username, 'System'),
    (actor_input).role,
    'Payment',
    action_input,
    before_input,
    after_input,
    nullif(trim(reason_input), '')
  );
$function$;

CREATE OR REPLACE FUNCTION private.write_ttc_audit(module_input text, action_input text, entity_input text, record_id_input text, before_input jsonb, after_input jsonb, reason_input text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  has_modern_shape boolean;
begin
  if to_regclass('public.audit_logs') is null then
    return;
  end if;

  select exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'audit_logs'
      and column_name in ('actor_type', 'entity', 'record_id')
    group by table_schema, table_name
    having count(*) = 3
  )
  into has_modern_shape;

  if has_modern_shape then
    insert into public.audit_logs(
      actor_id,
      actor_name,
      actor_type,
      actor_role,
      module,
      entity,
      record_id,
      action,
      before,
      after,
      reason
    )
    values(
      auth.uid(),
      null,
      case when auth.uid() is null then 'system' else null end,
      null,
      module_input,
      entity_input,
      record_id_input,
      action_input,
      before_input,
      after_input,
      nullif(trim(reason_input), '')
    );
  else
    insert into public.audit_logs(
      actor_id,
      actor_name,
      actor_role,
      module,
      action,
      before,
      after,
      reason
    )
    values(
      auth.uid(),
      null,
      null,
      module_input,
      action_input,
      before_input,
      after_input,
      nullif(trim(reason_input), '')
    );
  end if;
end;
$function$;
CREATE TRIGGER normalize_audit_log_trigger BEFORE INSERT ON public.audit_logs FOR EACH ROW EXECUTE FUNCTION private.normalize_audit_log();
CREATE TRIGGER prevent_audit_log_change_trigger BEFORE DELETE OR UPDATE ON public.audit_logs FOR EACH ROW EXECUTE FUNCTION private.prevent_audit_log_change();
CREATE TRIGGER customers_log_trigger AFTER INSERT OR DELETE OR UPDATE ON public.customers FOR EACH ROW EXECUTE FUNCTION log_changes();
CREATE TRIGGER kiosks_log_trigger AFTER INSERT OR DELETE OR UPDATE ON public.kiosks FOR EACH ROW EXECUTE FUNCTION log_changes();
CREATE TRIGGER on_kiosk_change AFTER INSERT OR DELETE OR UPDATE ON public.kiosks FOR EACH ROW EXECUTE FUNCTION update_customer_kiosk_count();
CREATE TRIGGER mirror_legacy_log_trigger AFTER INSERT ON public.logs FOR EACH ROW EXECUTE FUNCTION private.mirror_legacy_log();
CREATE TRIGGER prevent_legacy_log_change_trigger BEFORE DELETE OR UPDATE ON public.logs FOR EACH ROW EXECUTE FUNCTION private.prevent_audit_log_change();
CREATE TRIGGER finalize_registration_promotion_usage_trigger AFTER UPDATE OF payment_status ON public.payments FOR EACH ROW EXECUTE FUNCTION private.finalize_registration_promotion_usage();
CREATE TRIGGER protect_payment_records_trigger BEFORE INSERT OR DELETE OR UPDATE ON public.payments FOR EACH ROW EXECUTE FUNCTION private.protect_payment_records();
CREATE TRIGGER protect_payos_checkout_metadata_trigger BEFORE INSERT OR UPDATE ON public.payments FOR EACH ROW EXECUTE FUNCTION private.protect_payos_checkout_metadata();
CREATE TRIGGER sync_completed_payment_totals_trigger AFTER INSERT OR DELETE OR UPDATE ON public.payments FOR EACH ROW EXECUTE FUNCTION private.sync_completed_payment_totals();
CREATE CONSTRAINT TRIGGER sync_completed_renewal_kiosk_period_trigger AFTER UPDATE ON public.payments DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION private.sync_completed_renewal_kiosk_period();
CREATE TRIGGER sync_registration_period_from_completed_payment_trigger AFTER UPDATE OF payment_status, start_date, end_date ON public.payments FOR EACH ROW EXECUTE FUNCTION private.sync_registration_period_from_completed_payment();
CREATE TRIGGER claim_payos_active_slot_trigger BEFORE INSERT ON public.payos_orders FOR EACH ROW EXECUTE FUNCTION private.claim_payos_active_slot();
CREATE TRIGGER audit_promotion_change_trigger AFTER INSERT OR UPDATE ON public.promotions FOR EACH ROW EXECUTE FUNCTION private.audit_promotion_change();
CREATE TRIGGER normalize_promotion_code_trigger BEFORE INSERT OR UPDATE ON public.promotions FOR EACH ROW EXECUTE FUNCTION private.normalize_promotion_code();
CREATE TRIGGER protect_completed_batch_promotion_snapshot_trigger BEFORE UPDATE OF promotion_id, promotion_code, promotion_snapshot, subtotal_before_discount, eligible_subtotal, discount_amount, total_amount ON public.registration_batches FOR EACH ROW EXECUTE FUNCTION private.protect_completed_batch_promotion_snapshot();
CREATE TRIGGER finalize_cancelled_public_kiosk_from_legacy_trigger AFTER UPDATE OF status ON public.registration_requests FOR EACH ROW EXECUTE FUNCTION private.finalize_cancelled_public_kiosk_from_legacy();
CREATE TRIGGER guard_legacy_approval_against_live_public_checkout_trigger BEFORE UPDATE OF status ON public.registration_requests FOR EACH ROW EXECUTE FUNCTION private.guard_legacy_approval_against_live_public_checkout();
CREATE TRIGGER link_registration_request_payment_trigger BEFORE INSERT ON public.registration_requests FOR EACH ROW EXECUTE FUNCTION private.link_registration_request_payment();
CREATE TRIGGER normalize_registration_requested_period_trigger BEFORE INSERT OR UPDATE OF requested_start_date, requested_end_date, months ON public.registration_requests FOR EACH ROW EXECUTE FUNCTION private.normalize_registration_requested_period();
CREATE TRIGGER prevent_duplicate_pending_registration_trigger BEFORE INSERT OR UPDATE OF facebook_id, facebook_link, status ON public.registration_requests FOR EACH ROW EXECUTE FUNCTION private.prevent_duplicate_pending_registration();
CREATE TRIGGER sync_registration_payment_intent_trigger AFTER INSERT OR UPDATE OF payment_id ON public.registration_requests FOR EACH ROW EXECUTE FUNCTION private.sync_registration_payment_intent();
CREATE TRIGGER prevent_staff_history_delete_trigger BEFORE DELETE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION private.prevent_staff_history_delete();
set check_function_bodies=on;
